    ["Padding"] = "Relleno",
    ["Party, Raid, and Mythic Raid Group Frame layout, bars, auras, indicators, scope overrides and positions"] = "Diseño, barras, auras, indicadores, anulaciones de alcance y posiciones del marco de grupo, incursión y grupo de incursiones míticas.",
    ["Position"] = "Posición",
    ["Positions class bar ABOVE Essential Cooldowns"] = "Barra de clases de posiciones ARRIBA de enfriamientos esenciales",
    ["Preserve HP color on all unit frames"] = "Preserva el color HP en todos los marcos de las unidades.",
    ["Press Ctrl+C to copy:"] = "Presione Ctrl+C para copiar:",
    ["Preview follows the current castbar visibility, icon, text, and global color settings."] = "La vista previa sigue la configuración actual de visibilidad, ícono, texto y color global de la barra de lanzamiento.",
    ["Profile actions"] = "Acciones de perfil",
    ["Quick Setup: Detached Class Bar"] = "Configuración rápida: barra de clase independiente",
    ["Reload"] = "recargar",
    ["Rows"] = "Filas",
    ["Same setting as each unit page > Transparency. It uses this same HP track color; off here means at least one unit frame is off."] = "Misma configuración que cada página de unidad > Transparencia. Utiliza este mismo color de pista HP; apagado aquí significa que al menos un marco de unidad está apagado.",
    ["Secret aura (name/fingerprint matched)"] = "Aura secreta (nombre/fingerprint coincide)",
    ["Select:"] = "Seleccione:",
    ["Set Bar Background Tint to white and enable Custom color in Dark Mode. If black, enable Preserve HP color on all unit frames."] = "Establezca el tinte de fondo de la barra en blanco y habilite el color personalizado en el modo oscuro. Si es negro, habilite Preservar el color HP en todos los marcos de la unidad.",
    ["Setup Now"] = "Configurar ahora",
    ["Slot"] = "Ranura",
    ["Some layout changes rebuild frames, while visual changes apply instantly. If needed, close and reopen the menu or reload after large profile/import changes."] = "Algunos cambios de diseño reconstruyen los marcos, mientras que los cambios visuales se aplican instantáneamente. Si es necesario, cierre y vuelva a abrir el menú o vuelva a cargarlo después de cambios importantes en el perfil/import.",
    ["Syncs & anchors power bar to class resources"] = "Sincroniza y ancla la barra de energía a los recursos de la clase.",
    ["The active profile is saved per character. New characters start on this profile instead of Default."] = "El perfil activo se guarda por personaje. Los personajes nuevos empiezan con este perfil en lugar de Default.",
    ["This layer is off in settings and cannot be shown in preview."] = "Esta capa está desactivada en la configuración y no se puede mostrar en la vista previa.",
    ["Type a name here before creating or copying a profile."] = "Escriba un nombre aquí antes de crear o copiar un perfil.",
    ["Undo"] = "Deshacer",
    ["Unit Frame Preview"] = "Vista previa del marco de la unidad",
    ["Unit frame status icons are on each unit page. Group frame indicators are in Group Frames > Indicators."] = "Los iconos de estado del marco de la unidad se encuentran en cada página de la unidad. Los indicadores del marco de grupo se encuentran en Marcos de grupo > Indicadores.",
    ["Use /msuf to open MSUF2. The Dashboard also contains reset, support, profile, and scale tools."] = "Utilice /msuf para abrir MSUF2. El Panel también contiene herramientas de reinicio, soporte, perfil y escala.",
    ["Use Dashboard > Reset Positions for frame movers. Use Profiles only when you want to reset, copy, import, or replace profile data."] = "Utilice Panel > Restablecer posiciones para mover marcos. Utilice Perfiles solo cuando desee restablecer, copiar, importar o reemplazar datos de perfil.",
    ["Use Global Style > Bars for highlight borders and Group Frames > Indicators for role, threat, dispel, spell, corner, and raid-marker indicators."] = "Utilice Estilo global > Barras para resaltar bordes y Marcos de grupo > Indicadores para indicadores de rol, amenaza, disipación, hechizo, esquina y marcador de incursión.",
    ["Use Group Frames > Layout for size and spacing, Buffs & Debuffs for aura clutter, and Indicators for fixed-position status icons."] = "Utilice Marcos de grupo > Diseño para tamaño y espaciado, Mejoras y desventajas para desorden de aura e Indicadores para íconos de estado de posición fija.",
    ["Use Group Frames pages: Layout for size/growth/sorting, Health & Text for bars/text, Buffs & Debuffs for auras, and Indicators for status icons."] = "Utilice páginas de marcos de grupo: Diseño para tamaño/growth/sorting, Salud y texto para barras/text, Mejoras y desventajas para auras e Indicadores para íconos de estado.",
    ["Use MSUF Edit Mode to drag a single unit frame. Use the unit page > Anchoring when you need exact anchor targets or X/Y values."] = "Utilice el modo de edición MSUF para arrastrar un marco de una sola unidad. Utilice la página de la unidad > Anclaje cuando necesite objetivos de anclaje exactos o valores X/Y.",
    ["Use MSUF Edit Mode to drag supported castbars. Per-unit castbar enable/icon/text options are on each unit page; shared castbar style is in Global Style > Castbar."] = "Utilice el modo de edición MSUF para arrastrar barras de lanzamiento compatibles. Las opciones de habilitación de barra de lanzamiento por unidad/icon/text se encuentran en la página de cada unidad; El estilo de Castbar compartido está en Estilo global > Castbar.",
    ["Use MSUF Edit Mode to drag the player frame. For exact anchor or X/Y values, open Player > Anchoring after that."] = "Utilice el modo de edición MSUF para arrastrar el marco del reproductor. Para conocer los valores exactos de anclaje o X/Y, abra Reproductor > Anclaje después de eso.",
    ["Use the Dashboard scale controls for menu scale or UI scale. You can also resize the MSUF2 window from its corner."] = "Utilice los controles de escala del Panel para la escala del menú o la escala UI. También puedes cambiar el tamaño de la ventana MSUF2 desde su esquina.",
    ["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, GCD, text, and interrupt options."] = "Utilice la página de unidad para alternar barras de lanzamiento por unidad y Estilo global > Barra de transmisión para texturas compartidas, dirección, GCD, texto y opciones de interrupción.",
    ["Use this if HP Bar fade makes the empty health area disappear or look black. It keeps the same HP track color from Colors."] = "Utilícelo si el desvanecimiento de la barra HP hace que el área de salud vacía desaparezca o se vea negra. Mantiene el mismo color de pista HP de Colors.",
    ["Value:"] = "Valor:",
    ["View"] = "Ver",
    ["Welcome to Class Resources!"] = "¡Bienvenido a Recursos de clase!",
    ["WoW blocks some protected frame changes in combat. Leave combat, then apply layout, anchoring, enable/disable, profile, or protected-frame changes."] = "WoW bloquea algunos cambios de marco protegidos en combate. Deja el combate, luego aplica cambios de diseño, anclaje, enable/disable, perfil o marco protegido.",
    ["bottom"] = "abajo",
    ["change background color unit frames"] = "cambiar color de fondo de marcos de unidad",
    ["class-resource layout, behavior, style, auto-hide, detached power bar and alternative mana settings"] = "diseño de recursos de clase, comportamiento, estilo, ocultación automática, barra de energía separada y configuraciones de maná alternativas",
    ["click layers to hide - drag preview elements - arrows nudge selected"] = "haga clic en las capas para ocultarlas, arrastre los elementos de vista previa, las flechas empujen la selección",
    ["frame colors, class/NPC colors, power colors, castbar colors, aura colors and gameplay color settings"] = "colores de marco, colores de clase/NPC, colores de poder, colores de barra de lanzamiento, colores de aura y configuraciones de color de juego",
    ["gameplay enhancement settings such as combat text, crosshair and click-cast behavior"] = "Configuraciones de mejora del juego, como texto de combate, punto de mira y comportamiento de lanzamiento de clic.",
    ["gf_layout"] = "gf_layout",
    ["global castbar behavior, textures, GCD, boss castbar and interrupt indicator settings"] = "comportamiento global de castbar, texturas, GCD, boss castbar y configuración del indicador de interrupción",
    ["language/menu behavior, update pacing, tooltips, Blizzard-frame handling, minimap icon, sounds and range-fade settings"] = "idiomaComportamiento de /menu, ritmo de actualización, información sobre herramientas, manejo de marcos de Blizzard, ícono de minimapa, sonidos y configuración de desvanecimiento de rango",
    ["none"] = "ninguno",
    ["optional style/module settings such as MSUF Style and dropdown style"] = "configuraciones opcionales de style/module como estilo MSUF y estilo desplegable",
    ["scope disabled"] = "alcance deshabilitado",
    ["shared"] = "compartido",
    ["shared bar textures, gradients, rounded frame corners, absorb display, outlines, highlight borders, power smoothing and all per-unit/group bar overrides"] = "texturas de barra compartidas, degradados, esquinas de marco redondeadas, visualización de absorción, contornos, bordes resaltados, suavizado potente y todas las anulaciones de barras por unidad/group",
    ["shared font family, text style, name/power text coloring, name shortening and all per-unit/group font overrides"] = "familia de fuentes compartidas, estilo de texto, color de texto name/power, acortamiento de nombres y todas las anulaciones de fuentes por unidad/group",
    ["the entire active profile"] = "todo el perfil activo",
    ["uf_target"] = "uf_target",
    ["–"] = "–",
}
for k, v in pairs(MSUF_LOCALE_COVERAGE_esES) do
    if L[k] == nil or L[k] == k then L[k] = v end
end

L["|cffffd700MSUF:|r Group Frames reset to defaults."] = "|cffffd700MSUF:|r Marcos de grupo restablecidos a valores predeterminados."
L["|cffffd700MSUF:|r Preserve HP color uses the same HP track color from Colors, but some bar textures may look different."] = "|cffffd700MSUF:|r Preservar color de HP usa el mismo color de pista de HP de Colores, pero algunas texturas de barra pueden verse diferentes."
L["Click a handle to select - drag custom layers - arrow keys nudge selected; Blizzard is locked"] = "Haz clic en un controlador para seleccionar - arrastra capas personalizadas - las flechas mueven la selección; Blizzard está bloqueado"
L["Copy categories"] = "Categorías de copia"
L["Copy Selected"] = "Copiar selección"
L["Custom Anchor Frame"] = "Marco de ancla personalizado"
L["Custom anchor target (mouse picker)"] = "Objetivo de ancla personalizado (selector de ratón)"
L["Don't show again"] = "No mostrar de nuevo"
L["Frame disabled"] = "Marco desactivado"
L["Growth Direction"] = "Dirección de crecimiento"
L["Preserve HP color keeps the HP fill color while layer fade is active and draws missing health separately with the same HP track color from Colors.\n\nThis can help when HP Bar fade makes the empty HP area disappear or look black. Some custom textures may still look flat, dark, or different while this option is enabled."] = "Preservar color de HP mantiene el color de relleno de HP mientras el desvanecimiento de capa está activo y dibuja la salud faltante por separado con el mismo color de pista de HP de Colores.\n\nEsto puede ayudar cuando el desvanecimiento de la barra de HP hace que el área vacía desaparezca o se vea negra. Algunas texturas personalizadas aún pueden verse planas, oscuras o diferentes con esta opción activada."
L["Reset %s to defaults?\n\nThis resets %s for the active profile. Defaults are read from the current MSUF factory profile, so future default changes are used automatically."] = "¿Restablecer %s a los valores predeterminados?\n\nEsto restablece %s para el perfil activo. Los valores predeterminados se leen del perfil de fábrica actual de MSUF, por lo que los cambios futuros se usan automáticamente."
L["Reset %s to defaults?\n\nThis resets the entire active profile '%s' to the current MSUF factory defaults. Every menu in that profile will be affected."] = "¿Restablecer %s a los valores predeterminados?\n\nEsto restablece todo el perfil activo '%s' a los valores de fábrica actuales de MSUF. Todos los menús de ese perfil se verán afectados."
L["Reset Scopes"] = "Restablecer ámbitos"

--- MSUF runtime coverage copied into direct locale file
L["                   Confirm stages the reset; reload via /reload or MSUF Menu > Advanced > Factory Reset."] = "                   Confirmar prepara el reinicio; recarga con /reload o usa Menú MSUF > Avanzado > Restablecimiento de fábrica."
