L["  (then /reload OR MSUF Menu > Advanced > Factory Reset)"] = "  (después /reload O Menú MSUF > Avanzado > Restablecimiento de fábrica)"
L["  /msuf absorb    - Toggle showing total absorb amount in HP text."] = "  /msuf absorb    - Activa o desactiva la absorción total en el texto de vida."
L["  /msuf analytics off|on|status - Toggle Wago Analytics beta telemetry."] = "  /msuf analytics off|on|status - Controla la telemetría beta de Wago Analytics."
L["  /msuf fullreset - FULL factory reset (all profiles/settings)."] = "  /msuf fullreset - Restablecimiento COMPLETO de fábrica (todos los perfiles/ajustes)."
L["  /msuf gfhoverdebug on|off|status - Debug group-frame hover + tooltip paths."] = "  /msuf gfhoverdebug on|off|status - Depura rutas de hover y tooltip de marcos de grupo."
L["  /msuf help      - Show this help."] = "  /msuf help      - Muestra esta ayuda."
L["  /msuf reset     - Reset all MSUF frame positions and visibility to defaults."] = "  /msuf reset     - Restablece posiciones y visibilidad de todos los marcos MSUF."
L["  /msufdbgpos     - Toggle position drift debugger (overlay + chat log)."] = "  /msufdbgpos     - Activa el depurador de deriva de posición (superposición + registro de chat)."
