L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. Dispel Glow is unavailable only for Group Frame scopes where Blizzard controls the aura layer."] = "El modo Blizzard deja que WoW coloque los tipos de aura seleccionados. El modo MSUF personalizado permite controlar tamaño, crecimiento, posición, filtros y estilo. Brillo de disipación no está disponible solo en ámbitos de marcos de grupo donde Blizzard controla la capa de auras."
L["Blizzard renders cooldown/stack text for native Buffs and Debuffs. These text overlay fields only affect custom icons."] = "Blizzard muestra el texto de reutilización y acumulaciones de los beneficios y perjuicios nativos. Estos campos de texto solo afectan a iconos personalizados."
