L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. MSUF Dispel Highlights keep Blizzard icons while allowing MSUF's dispel border, glow, and overlay visuals."] = "El modo Blizzard deja que WoW coloque los tipos de aura seleccionados. El modo MSUF personalizado permite que MSUF controle tamaño, crecimiento, posición, filtros y estilo. Los resaltados de disipación de MSUF conservan los iconos de Blizzard y permiten que MSUF muestre el borde, el brillo y el overlay de disipación."
L["Blizzard renderer is still active, but this group is MSUF Custom because its Use Blizzard toggle is off. Other active Blizzard aura types can still show matching spells, so duplicates can appear."] = "El renderizador de Blizzard sigue activo, pero este grupo es MSUF Custom porque su interruptor Usar Blizzard esta desactivado. Otros tipos de aura de Blizzard activos pueden seguir mostrando hechizos coincidentes, asi que pueden aparecer duplicados."
