L["Attach the strip to the active Party, Raid, or Mythic Raid container, or choose Free position and place it with Edit Mode."] = "Acopla la franja al contenedor activo de grupo, banda o banda mítica, o elige Posición libre y colócala con el modo de edición."
L["Right of group frames"] = "A la derecha de los marcos de grupo"
L["Left of group frames"] = "A la izquierda de los marcos de grupo"
L["Above group frames"] = "Encima de los marcos de grupo"
L["Below group frames"] = "Debajo de los marcos de grupo"
L["The strip follows the active Party, Raid, or Mythic Raid container automatically."] = "La franja sigue automáticamente el contenedor activo de grupo, banda o banda mítica."
L["In party"] = "En grupo"
L["In raid"] = "En banda"
L["Not grouped"] = "Sin grupo"
L["Priority Frames keep automatic tanks and manually pinned group members in a stable extra strip. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. The matching base group frames must be enabled. Open Group Frames > Priority to choose who appears, set a hover hotkey, and place the strip."] = "Los marcos prioritarios mantienen los tanques automáticos y los miembros fijados manualmente en una franja adicional estable. En grupo heredan los marcos de grupo; en banda, los marcos activos de banda o banda mítica. Los marcos base correspondientes deben estar activados. Abre Marcos de grupo > Prioridad para elegir quién aparece, asignar una tecla y colocar la franja."
L["Free position uses the dedicated Priority Frames mover."] = "La posición libre usa el controlador propio de los marcos prioritarios."
L["How do Priority Frames work?"] = "¿Cómo funcionan los marcos prioritarios?"
L["Opens: Group Frames > Priority"] = "Abre: Marcos de grupo > Prioridad"
L["Pin or unpin hovered group member"] = "Fijar o soltar al miembro bajo el cursor"
L["Priority Frames hotkey"] = "Tecla de marcos prioritarios"
L["Left-click and press a key. Right-click, Backspace, or Delete clears it. Existing bindings are never replaced without confirmation."] = "Haz clic izquierdo y pulsa una tecla. Clic derecho, Retroceso o Suprimir la borran. Las asignaciones existentes nunca se sustituyen sin confirmación."
