L["Health gradient color"] = "Color degradado de salud"
L["Power gradient color"] = "Color del gradiente de potencia"
L["Border & fill"] = "Borde y relleno"
L["Detached placement"] = "Colocación separada"
L["Reset gradient colors"] = "Restablecer colores degradados"
L["Health and Power use separate gradient colors. Choosing a color creates a custom Bars override for the selected scope."] = "Salud y Poder usan colores degradados separados. Al elegir un color se crea una anulación de barras personalizada para el ámbito seleccionado."
L["UPGRADED TO MSUF %s"] = "ACTUALIZADO A MSUF %s"
L["Your MSUF 6.0 highlights"] = "Lo más destacado de MSUF 6.0"
L["Your current profile stays unchanged. Review %d new highlights and choose only what you want to configure."] = "Su perfil actual permanece sin cambios. Revise las novedades destacadas de %d y elija solo lo que desea configurar."
L["CURRENT PROFILE: %s - NO SETTINGS WILL BE CHANGED"] = "PERFIL ACTUAL: %s - NO SE CAMBIARÁ NINGUNA CONFIGURACIÓN"
L["Start %d-highlight tour"] = "Iniciar el recorrido más destacado de %d"
L["Review the release highlights without changing your current profile."] = "Revise los aspectos más destacados del lanzamiento sin cambiar su perfil actual."
L["Review exactly what you would skip before closing the tour."] = "Revisa exactamente lo que te saltarías antes de cerrar el recorrido."
L["About two minutes. You can leave at any point and configure each area later."] = "Unos dos minutos. Puedes salir en cualquier punto y configurar cada área más tarde."
L["Highlight %d of %d"] = "Resalte %d de %d"
L["WHY IT MATTERS"] = "POR QUÉ IMPORTA"
L["Finish tour"] = "Terminar el recorrido"
L["Next highlight"] = "Siguiente punto culminante"
L["Mark this highlight as reviewed and continue."] = "Marque este punto destacado como revisado y continúe."
L["Back"] = "Atrás"
L["Skip tour"] = "Saltar recorrido"
L["See the remaining highlights before deciding to skip them."] = "Vea los aspectos más destacados restantes antes de decidir omitirlos."
L["Skip %d remaining highlights?"] = "¿Omitir los aspectos destacados restantes de %d?"
L["Your profile will stay safe, but you will leave these %d new configuration areas unexplored:"] = "Tu perfil permanecerá seguro, pero dejarás estas nuevas áreas de configuración %d sin explorar:"
L["Show me the highlights"] = "Muéstrame los aspectos más destacados"
L["Skip all %d and continue"] = "Saltar todo %d y continuar"
L["Skipping closes this release tour only. Every setting remains available in Menu2."] = "Omitir cierra este recorrido de lanzamiento únicamente. Cada configuración permanece disponible en el Menú 2."
L["Custom Aura tracking on Unitframes"] = "Seguimiento de aura personalizado en Unitframes"
L["Build up to three frame-specific Custom lanes on Player, Target, Focus and Boss, whitelist exact buff or debuff SpellIDs, and track your own DoTs on the Target frame with a curated per-class lane."] = "Crea hasta tres carriles personalizados en Jugador, Objetivo, Foco y Jefe, añade SpellID exactos de beneficios o perjuicios, y sigue tus propios DoTs en el Objetivo con un carril por clase."
L["Your MSUF frames can act as focused WeakAura-style trackers with icons, timers, duration bars and full-frame tint, border, glow or pulse effects."] = "Sus marcos MSUF pueden actuar como rastreadores enfocados estilo WeakAura con íconos, temporizadores, barras de duración y efectos de tinte, borde, brillo o pulso de marco completo."
L["three Custom Aura trackers per supported Unitframe, exact spell whitelists and full-frame effects"] = "tres rastreadores de aura personalizados por unidad de marco compatible, listas blancas de hechizos exactas y efectos de marco completo"
L["Build a Custom tracker"] = "Crear un rastreador personalizado"
L["Aura settings in the right place"] = "Ajustes de aura en el lugar adecuado"
L["Setup and individual styling now live in the matching Unitframe and Party/Raid menus. Appearance > Auras holds the expanded shared styles."] = "La configuración y el estilo individual están ahora en los menús correspondientes de marcos de unidad y grupo/banda. Apariencia > Auras contiene los estilos compartidos ampliados."
L["Configure each frame in context, then use Auras for shared icon shapes, borders, shadows, colors and spacing."] = "Configura cada marco en su contexto y usa Auras para compartir formas de icono, bordes, sombras, colores y espaciado."
L["per-frame Aura controls and expanded shared styling in Appearance > Auras"] = "controles de aura por marco y estilo compartido ampliado en Apariencia > Auras"
L["Open shared Aura styles"] = "Abrir estilos de aura compartidos"
L["Adaptive Party and Raid layouts"] = "Diseños adaptables de grupo y raid"
L["Party, Raid and Mythic Raid gained adaptive layouts and scaling, per-lane aura filters and blacklists, a focused Dispel Overlay page, and per-group control over whether MSUF or Blizzard draws the frames."] = "Grupo, Banda y Banda mítica ganaron diseños adaptativos con escalado, filtros y listas negras de auras por carril, una página dedicada de Dispel Overlay, y tú decides por tipo de grupo si MSUF o Blizzard dibuja los marcos."
L["One group setup can follow you from a five-man into a raid, and you decide per lane which auras are allowed to show at all."] = "Una sola configuración de grupo puede acompañarte desde una mazmorra de cinco hasta una banda, y decides por línea qué auras pueden aparecer siquiera."
L["adaptive group layouts and scaling, group aura filters and blacklists, the Dispel Overlay page and the group provider controls"] = "los diseños adaptativos y el escalado, los filtros y listas negras de auras de grupo, la página de Dispel Overlay y el control del proveedor por grupo"
L["Open Group Layout"] = "Diseño de grupo abierto"
L["New health values and text formats"] = "Nuevos valores de salud y formatos de texto."
L["Health text can show abbreviated or full values with more consistent formatting, and the new Maximum Health Loss overlay can mark lost maximum health on unit and group frames."] = "El texto de salud puede mostrar valores abreviados o completos con un formato más consistente, y la nueva superposición de salud máxima perdida marca la salud máxima reducida en marcos de unidad y de grupo."
L["You can choose compact readability or exact numbers without giving up the layout you already use."] = "Puede elegir legibilidad compacta o números exactos sin renunciar al diseño que ya utiliza."
L["the new health abbreviations, full values, text formats and the Maximum Health Loss overlay"] = "las nuevas abreviaturas de salud, los valores completos, los formatos de texto y la superposición de salud máxima perdida"
L["Open HP Text Editor"] = "Abrir el editor de texto de vida"
L["More flexible class resources"] = "Recursos de clase más flexibles"
L["Class resources gained detached layouts, additional shapes and finer per-slot and full-state colors."] = "Los recursos de clase obtuvieron diseños independientes, formas adicionales y colores más finos por ranura y de estado completo."
L["You can move class information where your eyes already are and make important states easier to read."] = "Puede mover la información de la clase donde ya están sus ojos y hacer que los estados importantes sean más fáciles de leer."
L["detached class resources, new shapes and per-state colors"] = "Recursos de clases independientes, nuevas formas y colores por estado."
L["Configure Class Resources"] = "Configurar recursos de clase"
L["Cast target text"] = "Transmitir texto de destino"
L["Target, Focus and Boss cast bars can now show who the current spell is targeting, with dedicated text styling."] = "Las barras de lanzamiento de Objetivo, Enfoque y Jefe ahora pueden mostrar a quién apunta el hechizo actual, con un estilo de texto dedicado."
L["You can identify the destination of an important cast without shifting attention away from the cast bar."] = "Puede identificar el destino de un lanzamiento importante sin desviar la atención de la barra de lanzamiento."
L["cast-target names and their text styling on Target, Focus and Boss frames"] = "nombres de objetivos de lanzamiento y su estilo de texto en los marcos de Objetivo, Enfoque y Jefe"
L["Open Target Cast Bar"] = "Abrir barra de lanzamiento de objetivo"
L["Review or skip the release highlights on the Dashboard before using first-load actions."] = "Revise u omita los aspectos destacados de la versión en el Panel antes de utilizar acciones de primera carga."
L["Priority Frames for the units that matter"] = "Marcos prioritarios para las unidades que importan"
L["Pin up to five group members by hand, or let MSUF pick the tanks automatically, and give them their own strip that never reshuffles mid-fight."] = "Fija hasta cinco miembros del grupo a mano, o deja que MSUF elija los tanques automáticamente, y dales su propia tira que nunca se reordena en mitad del combate."
L["The people you have to watch keep one fixed spot on screen, with the Party or Raid look and click-casting they already had."] = "Las personas que debes vigilar mantienen un sitio fijo en pantalla, con el aspecto de grupo o banda y el lanzamiento por clic que ya tenían."
L["Priority Frames, manual and automatic pinning, and their own placement"] = "los marcos prioritarios, la fijación manual y automática y su propia colocación"
L["Set up Priority Frames"] = "Configurar marcos prioritarios"
L["One Colors page with click-to-paint"] = "Una página de colores con pintar al hacer clic"
L["Every color moved onto one page, grouped into Player & Target, Party & Raid, Castbar, Aura, Power and Class Resource workspaces with their own live preview."] = "Todos los colores se han movido a una sola página, agrupados en espacios de trabajo de Jugador y objetivo, Grupo y banda, Barra de lanzamiento, Auras, Energía y Recursos de clase, cada uno con su vista previa en vivo."
L["You can click the element in the preview to paint it instead of hunting for the matching swatch, and reuse any color from a recent or saved palette."] = "Puedes hacer clic en el elemento de la vista previa para pintarlo en lugar de buscar la muestra correspondiente, y reutilizar cualquier color de una paleta reciente o guardada."
L["the rebuilt Colors page, click-to-paint previews, palettes and the new color picker"] = "la página de colores rediseñada, las vistas previas para pintar al hacer clic, las paletas y el nuevo selector de color"
L["Open the Colors page"] = "Abrir la página de colores"
L["One 0-30 layer scale for everything"] = "Una escala de capas 0-30 para todo"
L["Text, status icons, auras, borders, bar outlines, group indicators and class resources all order themselves on one shared 0-30 layer scale."] = "Textos, iconos de estado, auras, bordes, contornos de barra, indicadores de grupo y recursos de clase se ordenan en una única escala de capas 0-30 compartida."
L["You decide exactly what draws in front of what, and the Layer Overview beside any layer slider shows the whole stack at once."] = "Decides exactamente qué se dibuja delante de qué, y el resumen de capas junto a cualquier deslizador de capa muestra toda la pila de una vez."
L["the addon-wide 0-30 layer scale and the Layer Overview"] = "la escala de capas 0-30 de todo el addon y el resumen de capas"
L["MSUF Edit Mode, rebuilt"] = "El modo de edición de MSUF, reconstruido"
L["Edit Mode gained a dockable toolbar, redesigned quick popups on every frame, and Undo and Redo that behave the same there as in the menu."] = "El modo de edición ganó una barra de herramientas acoplable, menús rápidos rediseñados en cada marco y Deshacer y Rehacer que funcionan igual que en el menú."
L["You can move, size and copy frames directly on screen and step back out of any mistake without reopening the menu."] = "Puedes mover, redimensionar y copiar marcos directamente en pantalla y deshacer cualquier error sin volver a abrir el menú."
L["the rebuilt Edit Mode toolbar, its quick popups and shared Undo and Redo"] = "la nueva barra de herramientas del modo de edición, sus menús rápidos y el Deshacer y Rehacer compartidos"
L["Start Edit Mode"] = "Iniciar el modo de edición"
L["Spell Indicators on Group Frames"] = "Spell Indicators en los marcos de grupo"
L["Track chosen buffs on Party and Raid frames as icon, square, bar or number indicators, with custom spell lists and corner indicators."] = "Sigue beneficios elegidos en los marcos de grupo y banda como icono, cuadrado, barra o número, con listas de hechizos personalizadas e indicadores de esquina."
L["You can see missing or expiring externals and key buffs directly on the frames, with expiring icon glows, health-bar highlights and full-frame effects."] = "Ves los externals que faltan o expiran y los beneficios clave directamente en los marcos, con brillo de expiración, resaltado de la barra de salud y efectos en todo el marco."
L["Spell Indicators with custom aura lists, corner indicators and expiring-effect warnings"] = "los Spell Indicators con listas de auras personalizadas, indicadores de esquina y avisos de expiración"
L["Open Spell Indicators"] = "Abrir Spell Indicators"
L["Fill Direction for Health and Power"] = "Dirección de llenado de Salud y Poder"
L["Every Unit Frame can fill its Health and Power left to right, right to left, bottom to top or top to bottom."] = "Cada marco de unidad puede llenar su Salud y Poder de izquierda a derecha, derecha a izquierda, de abajo arriba o de arriba abajo."
L["Vertical and mirrored bar layouts become a per-frame choice - something no other unit frame addon currently offers."] = "Los diseños verticales o en espejo pasan a ser una opción por marco: algo que ningún otro addon de unit frames ofrece actualmente."
L["the per-frame Fill Direction control for Health and Power bars"] = "el control de dirección de llenado por marco para las barras de Salud y Poder"
L["Choose a Fill Direction"] = "Elegir dirección de llenado"
L["Portraits: attached, detached or overlay"] = "Retratos: anclado, separado u overlay"
L["Portraits can stay attached, float freely or render as an overlay inside the health bar, with independent size, nine-point anchoring, opacity and pannable zoom."] = "Los retratos pueden quedarse anclados, flotar libres o dibujarse como overlay dentro de la barra de salud, con tamaño independiente, anclaje de nueve puntos, opacidad y zoom desplazable."
L["Rectangular and watermark-style portraits become possible, and Relief rings plus shape-following borders frame Square, Circle, Rounded and Diamond portraits."] = "Los retratos rectangulares o de marca de agua se vuelven posibles, y los anillos Relief más los bordes que siguen la forma enmarcan retratos cuadrados, circulares, redondeados y de diamante."
L["the new portrait placement modes, Relief rings and shape-following portrait borders"] = "los nuevos modos de colocación de retratos, los anillos Relief y los bordes que siguen la forma"
L["Open Portrait settings"] = "Abrir ajustes de retrato"
L["Status icon packs"] = "Paquetes de iconos de estado"
L["Role, leader, raid marker, ready check and every other status icon can switch between twelve bundled styles or your own custom icons, per indicator."] = "Rol, líder, marcador de banda, comprobación de preparación y cualquier otro icono de estado pueden cambiar entre doce estilos incluidos o tus propios iconos, por indicador."
L["Status icons can finally match your UI style instead of always using Blizzard art, and external packs can register through SharedMedia."] = "Los iconos de estado por fin pueden encajar con tu interfaz en lugar del arte de Blizzard, y los paquetes externos pueden registrarse mediante SharedMedia."
L["the twelve status icon styles and per-indicator custom icons"] = "los doce estilos de iconos de estado y los iconos personalizados por indicador"
L["Pick an icon style"] = "Elegir un estilo de iconos"
L["Old"] = "Viejo"
