L["Double-click or use the settings button to open this element's settings."] = "Haga doble clic o use el botón de configuración para abrir la configuración de este elemento."
L["Right-click opens quick actions."] = "Al hacer clic derecho se abren acciones rápidas."
L["double-click/settings opens options - right-click actions - arrows nudge"] = "hacer doble clic en /settings abre opciones - acciones de clic derecho - flechas empujadas"
L["drag handles - double-click/settings opens options - right-click actions - Ctrl+wheel zoom"] = "arrastre los controladores - haga doble clic/settings abre opciones - haga clic con el botón derecho en acciones - Ctrl+zoom con rueda"
L["Click a handle to select - double-click/settings opens options - right-click actions - Ctrl+wheel zoom"] = "Haga clic en un controlador para seleccionar - haga doble clic en /settings abre opciones - haga clic con el botón derecho en acciones - Ctrl+zoom con rueda"
L["Preview tip: drag handles to move, double-click or use settings to open options, right-click for actions."] = "Consejo de vista previa: arrastre los controladores para mover, haga doble clic o use la configuración para abrir opciones, haga clic derecho para realizar acciones."
L["Hide right % sign"] = "Ocultar a la derecha % sign"
