L["Hide center % sign"] = "Ocultar centro % sign"
L["Group frames were enabled or disabled.\n\nA UI reload is required to fully apply this change.\n\nReload now?"] = "Los marcos de grupo se habilitaron o deshabilitaron.\n\nA Se requiere recargar la interfaz de usuario para aplicar completamente este cambio.\n\n¿Recargar ahora?"
L["|cffffd700MSUF:|r Group frames were enabled or disabled. Reload the UI with /reload."] = "|cffffd700MSUF:|r Se habilitaron o deshabilitaron tramas de grupo. Vuelva a cargar la interfaz de usuario con /reload."
