L["Party and raid layout"] = "Diseño de grupo y raid"
L["Group health and text"] = "Salud del grupo y texto"
L["Group indicators"] = "Indicadores de grupo"
L["Group auras"] = "auras grupales"
L["Bars and textures"] = "Barras y texturas"
L["Cast bars"] = "barras fundidas"
L["Fonts and text"] = "Fuentes y texto"
L["Aura styling"] = "Estilo de aura"
L["Menu and miscellaneous"] = "Menú y varios"
L["Class resources"] = "Recursos de clase"
L["Gameplay features"] = "Características del juego"
L["Profiles and backup"] = "Perfiles y copia de seguridad"
L["Review your guided setup"] = "Revise su configuración guiada"
L["Skipping this personal step uses neutral guidance and leaves navigation, Search, autosave, Undo/Redo and page reset unexplained."] = "Omitir este paso personal utiliza una guía neutral y deja sin explicación la navegación, la búsqueda, el guardado automático, la función Deshacer/Redo y el restablecimiento de página."
L["Skipping frame placement leaves whole-frame movement, snapping, nudging and safe exit behavior unexplained."] = "Saltarse la colocación del marco deja sin explicación el movimiento de todo el marco, los chasquidos, los empujones y el comportamiento de salida segura."
L["Skipping the Player frame leaves its layout, text, indicators and aura options unreviewed."] = "Al omitir el marco del Reproductor, su diseño, texto, indicadores y opciones de aura no se revisan."
L["Skipping the Target frame leaves its layout, text, indicators and aura options unreviewed."] = "Al omitir el marco de destino, su diseño, texto, indicadores y opciones de aura no se revisan."
L["Skipping the Focus frame leaves its layout, text, indicators and aura options unreviewed."] = "Al omitir el cuadro de enfoque, su diseño, texto, indicadores y opciones de aura no se revisan."
L["Skipping the Pet frame leaves its layout, text, indicators and aura options unreviewed."] = "Al omitir el marco de la mascota, su diseño, texto, indicadores y opciones de aura no se revisan."
L["Skipping Target of target leaves its layout, text and visibility options unreviewed."] = "Al omitir el destino del destino, sus opciones de diseño, texto y visibilidad no se revisan."
L["Skipping Focus target leaves its layout, text and visibility options unreviewed."] = "Al omitir el objetivo de enfoque, sus opciones de diseño, texto y visibilidad no se revisan."
L["Skipping Boss frames leaves their shared layout, text, indicators and aura options unreviewed."] = "Saltarse los marcos de Boss deja sin revisar el diseño, el texto, los indicadores y las opciones de aura compartidos."
L["Skipping group layout leaves frame size, growth, sorting, scaling and anchoring unreviewed."] = "Al omitir el diseño del grupo, el tamaño del marco, el crecimiento, la clasificación, la escala y el anclaje no se revisan."
L["Skipping group bars leaves health, power, text, range and dispel presentation unreviewed."] = "Saltarse las barras de grupo deja sin revisar la presentación de salud, potencia, texto, rango y disipación."
L["Skipping group auras leaves group buff, debuff and spell-indicator behavior unreviewed."] = "Saltarse las auras grupales deja sin revisar el comportamiento de las ventajas y desventajas del grupo y del indicador de hechizos."
L["Skipping Bars leaves global textures, absorbs, outlines, highlights and power behavior unreviewed."] = "Saltar barras deja sin revisar las texturas globales, las absorciones, los contornos, las luces y el comportamiento de potencia."
L["Skipping Cast Bars leaves cast appearance, text, empowered casts and interrupt cues unreviewed."] = "Al omitir las barras de lanzamiento, la apariencia del lanzamiento, el texto, los lanzamientos potenciados y las señales de interrupción no se revisan."
L["Skipping Colors leaves frame, power, aura, class, text and castbar colors unreviewed."] = "Omitir colores deja sin revisar los colores del marco, el poder, el aura, la clase, el texto y la barra de lanzamiento."
L["Skipping Fonts leaves the global font, text styling, colors and name shortening unreviewed."] = "Al omitir fuentes, la fuente global, el estilo del texto, los colores y el acortamiento del nombre no se revisan."
L["Skipping Aura styling leaves buff/debuff size, cooldown, stacks, duration bars and ordering unreviewed."] = "Omitir el estilo del aura deja sin revisar el tamaño, el tiempo de reutilización, las acumulaciones, las barras de duración y el orden de buff/debuff."
L["Skipping Miscellaneous leaves language, menu behavior, startup, tooltips and Blizzard-frame integration unreviewed."] = "Omitir Varios deja sin revisar el idioma, el comportamiento del menú, el inicio, la información sobre herramientas y la integración de Blizzard-frame."
L["Skipping Class Resources leaves class layout, behavior, style, visibility and alternative power displays unreviewed."] = "Saltarse los recursos de la clase deja sin revisar el diseño de la clase, el comportamiento, el estilo, la visibilidad y las presentaciones de poder alternativo."
L["Skipping Gameplay leaves combat timers, state behavior, class toggles and the combat crosshair unreviewed."] = "Saltarse el juego deja sin revisar los cronómetros de combate, el comportamiento de estado, los cambios de clase y la mira de combate."
L["Skipping Profiles leaves profile management, specialization assignment and export/import backup unreviewed."] = "Omitir perfiles deja sin revisar la administración de perfiles, la asignación de especialización y la copia de seguridad export/import."
L["Skipping the final review hides the summary, but does not change any setting."] = "Saltarse la revisión final oculta el resumen, pero no cambia ninguna configuración."
