L["Spell-specific channel tick markers"] = "Marcadores de marca de canal específicos del hechizo"
L["Runs a short castbar for the global cooldown whenever an instant spell triggers it.\n\nThe fill and time text are driven natively by the client from the real (haste-scaled) GCD duration - no per-frame addon work while the bar runs. A real cast, channel or empower always takes priority."] = "Muestra una barra de lanzamiento corta para el tiempo de reutilización global cuando un hechizo instantáneo lo activa.\n\nEl relleno y el texto de tiempo los controla el cliente de forma nativa a partir de la duración real del GCD (ajustada por celeridad); el complemento no realiza trabajo por marco mientras la barra está activa. Un lanzamiento real, una canalización o un hechizo potenciado siempre tiene prioridad."
L["Shows tick separators on the Player castbar while channeling.\n\nSupported spells use their actual tick count, including supported talent and channel-duration changes. Unsupported channels keep five evenly spaced fallback lines. Custom channel tick settings override the automatic layout.\n\nThe markers are event-driven and add no recurring channel polling."] = "Muestra separadores de ticks en la barra de lanzamiento del jugador mientras se canaliza.\n\nLos hechizos admitidos utilizan su recuento de ticks real, incluidos los talentos admitidos y los cambios de duración del canal. Los canales no compatibles mantienen cinco líneas de reserva espaciadas uniformemente. La configuración de marca de canal personalizada anula el diseño automático.\n\nLos marcadores se basan en eventos y no agregan sondeos de canales recurrentes."
L["Class Color (Reaction fallback)"] = "Color de clase (reacción alternativa)"
L["Ready color (kick available)"] = "Color listo (patada disponible)"
L["Not ready color (kick on cooldown)"] = "Color no listo (activación en tiempo de reutilización)"
L["PvP Flag (War Mode/PvP)"] = "Bandera PvP (Modo Guerra/PvP)"
L["Abbreviate HP values (K/M)"] = "Valores abreviados de HP (K/M)"
L["For specializations that use mana alongside another resource."] = "Para especializaciones que usan maná junto con otro recurso."
L["Smooths resource changes. Runes, Essence recharge, and timers keep their own animation."] = "Suaviza los cambios de recursos. Las runas, la recarga de esencia y los temporizadores mantienen su propia animación."
L["Exact Spell IDs are used when Blizzard exposes them."] = "Los ID de hechizos exactos se utilizan cuando Blizzard los expone."
L["Reverses only the swipe overlay. Icon size and position stay unchanged."] = "Invierte solo la superposición de deslizamiento. El tamaño y la posición del icono permanecen sin cambios."
L["Only relevant sorting methods are shown for buffs and debuffs."] = "Solo se muestran los métodos de clasificación relevantes para ventajas y desventajas."
L["Reversed flips the complete priority order."] = "Invertido invierte el orden de prioridad completo."
L["Choose which auras Blizzard provides for this lane."] = "Elige qué auras proporciona Blizzard para este carril."
