L["This preview layer is locked."] = "Esta capa de vista previa está bloqueada."
L["Timer and marker colors are shared by unit and group aura previews."] = "Los colores del temporizador y del marcador son compartidos por las vistas previas del aura de unidad y grupo."
L["Timer urgency, ownership, stacks and pandemic state."] = "Urgencia del temporizador, propiedad, acumulaciones y estado de pandemia."
L["Tune Party range fade"] = "Desvanecimiento del rango Tune Party"
L["Two arrows point to a movable frame. Drag it once; Next unlocks after a real position change."] = "Two arrows point to a movable frame. Arrástralo una vez; Luego se desbloquea después de un cambio de posición real."
L["Type a new value, then press Enter."] = "Escriba un nuevo valor y luego presione Entrar."
L["UNLOCK, THEN CHANGE IT - Enable Corner Indicators, choose a slot, then select Custom Spell when requested."] = "DESBLOQUEAR, LUEGO CAMBIARLO: habilite los indicadores de esquina, elija una ranura y luego seleccione Hechizo personalizado cuando se le solicite."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spec, then press a tracked spell tile."] = "DESBLOQUEARLO, LUEGO CAMBIARLO: habilite los indicadores de hechizo, elija una especialización y luego presione un mosaico de hechizo rastreado."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then select a Frame Effect."] = "DESBLOQUEAR, LUEGO CAMBIARLO: habilite los indicadores de hechizo, elija un hechizo y luego seleccione un efecto de marco."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then set Indicator Type."] = "DESBLOQUEAR, LUEGO CAMBIARLO: habilite los indicadores de hechizo, elija un hechizo y luego configure el tipo de indicador."
L["UNLOCK, THEN CHANGE IT - Enable the parent feature in this section first."] = "DESBLOQUEAR, LUEGO CAMBIARLO: primero habilite la función principal en esta sección."
L["UNLOCK, THEN CHANGE IT - Turn on Spell Indicators in the earlier checkpoint; use Back if you skipped it."] = "DESBLOQUEARLO, LUEGO CAMBIARLO: active los indicadores de hechizo en el punto de control anterior; use Atrás si lo omitió."
L["Unit frame status icons are on each unit page. Group Spell Indicators are in Group Frames > Auras; group status and corner indicators are in Group Frames > Status & Indicators."] = "Los iconos de estado del marco de la unidad se encuentran en cada página de la unidad. Los indicadores de hechizos de grupo se encuentran en Marcos de grupo > Auras; El estado del grupo y los indicadores de las esquinas se encuentran en Marcos de grupo > Estado e indicadores."
