-- MSUF FULL CORE MENU SOURCE INVENTORY 2
-- Generated missing non-Assistant core keys for esES.
L["+"] = "+"
L["Can Priority Frames automatically select healers, DPS, classes, or specs?"] = "¿Puede Priority Frames seleccionar automáticamente sanadores, DPS, clases o especificaciones?"
L["Can Priority Frames automatically show Augmentation Evokers?"] = "¿Pueden los marcos de prioridad mostrar automáticamente los evocadores de aumento?"
L["Can Priority Frames show my co-tank?"] = "¿Puede Priority Frames mostrar mi co-tanque?"
L["Can Priority Frames update during combat?"] = "¿Se pueden actualizar los Priority Frames durante el combate?"
L["Check that Priority Frames are enabled, you are grouped, and the matching base Party or Raid frames are enabled. Confirm that an assigned tank or manually pinned player is currently in the group and Visible slots is not full. Saved absent players create no empty placeholders, and protected roster changes made in combat finish after combat ends."] = "Comprueba que los marcos prioritarios estén habilitados, que estés agrupado y que los marcos base de grupo o incursión correspondientes estén habilitados. Confirma que un tanque asignado o un jugador fijado manualmente esté actualmente en el grupo y que los espacios visibles no estén llenos. Los jugadores ausentes guardados no crean marcadores de posición vacíos y los cambios en la lista protegida realizados en el combate finalizan una vez finalizado el combate."
L["Class Color and Health Gradient are runtime colors, not a single editable swatch."] = "El color de clase y el degradado de salud son colores en tiempo de ejecución, no una sola muestra editable."
L["Cleave Training Dummy"] = "Chupete de entrenamiento Cleave"
L["Custom 1-3 are always stored per frame. Icon styling and Full-Frame effects here only change "] = "Los personalizados 1-3 siempre se almacenan por cuadro. El estilo de los iconos y los efectos de marco completo aquí solo cambian"
L["Disabled or whitelist empty"] = "Deshabilitado o lista blanca vacía"
L["Do Priority Frame pins persist, and what order do they use?"] = "¿Persisten los pines del marco de prioridad y en qué orden se utilizan?"
L["Do Priority Frames inherit click casting and appearance?"] = "¿Los Priority Frames heredan la apariencia y el casting de clics?"
L["Do Priority Frames use polling?"] = "¿Los marcos de prioridad utilizan encuestas?"
L["Do Priority Frames work in parties and dungeons?"] = "¿Los marcos de prioridad funcionan en grupos y mazmorras?"
L["Enter text"] = "Introducir texto"
L["Existing Priority frames remain usable in combat, but WoW protects secure group-frame membership and layout changes. Any pin, roster, slot, or placement change that needs a secure refresh is applied after combat ends. Change the Priority Frames keybinding out of combat."] = "Los marcos de prioridad existentes siguen siendo utilizables en combate, pero WoW protege la membresía segura del marco de grupo y los cambios de diseño. Cualquier cambio de pin, lista, ranura o ubicación que necesite una actualización segura se aplica una vez finalizado el combate. Cambia la combinación de teclas de los marcos prioritarios fuera de combate."
L["Follows Unitframe Global Coloring. The swatch previews the current global bar color."] = "Sigue la coloración global de Unitframe. La muestra muestra una vista previa del color de la barra global actual."
L["For Priority Frames, layout is profile-wide, while pins are character-specific. Visible slots can be set from one to five. Automatic tanks fill first, followed by manual pins in saved order; duplicate selections appear once. A saved player who is absent waits until that player rejoins the current group."] = "Para los marcos prioritarios, el diseño abarca todo el perfil, mientras que los pines son específicos de cada carácter. Las ranuras visibles se pueden configurar de una a cinco. Primero se llenan los tanques automáticos, seguidos por los pasadores manuales en el orden guardado; Las selecciones duplicadas aparecen una vez. Un jugador guardado que está ausente espera hasta que ese jugador se reincorpore al grupo actual."
L["How do I pin or unpin a player in Priority Frames?"] = "¿Cómo puedo fijar o desanclar a un jugador en Priority Frames?"
L["How do I position Priority Frames?"] = "¿Cómo coloco los marcos prioritarios?"
L["How should an Augmentation Evoker use Priority Frames?"] = "¿Cómo debería un evocador de aumento utilizar marcos de prioridad?"
L["Inherited: this scope follows Shared aura style. Enable custom aura style only when this scope needs different text, swipe, border, or timer settings."] = "Heredado: este alcance sigue el estilo de aura compartida. Habilite el estilo de aura personalizado solo cuando este alcance necesite diferentes configuraciones de texto, deslizamiento, borde o temporizador."
L["Leave text"] = "dejar texto"
L["Live "] = "en vivo"
L["Live preview is unavailable for this container. Sample mode remains available."] = "La vista previa en vivo no está disponible para este contenedor. El modo de muestra sigue estando disponible."
L["Live preview updates after combat. Sample mode remains available."] = "Actualizaciones de vista previa en vivo después del combate. El modo de muestra sigue estando disponible."
L["Manually pin the teammates you want to keep visible for monitoring or click-casting. Priority Frames does not decide who should receive Prescience or Ebon Might. Configure Group Frames > Auras > Spell Indicators if you want inherited Priority frames to show Prescience, Ebon Might, Shifting Sands, Blistering Scales, or other configured effects."] = "Fija manualmente a los compañeros de equipo que deseas mantener visibles para monitorear o hacer clic. Priority Frames no decide quién debe recibir Presscience o Ebon Might. Configure Marcos de grupo > Auras > Indicadores de hechizo si desea que los marcos de prioridad heredados muestren Presciencia, Poder de ébano, Arenas movedizas, Escamas ampollas u otros efectos configurados."
L["Native · "] = "Nativo ·"
L["No continuous polling ticker or OnUpdate loop is used for Priority selection. It resolves the roster when configuration, pins, group state, or relevant unit identity changes require a refresh. Automatic selection reads WoW's assigned TANK role and does not inspect every group member's specialization in the background."] = "No se utiliza ningún ticker de sondeo continuo ni bucle OnUpdate para la selección de Prioridad. Resuelve la lista cuando la configuración, los pines, el estado del grupo o los cambios relevantes en la identidad de la unidad requieren una actualización. La selección automática lee el rol de TANQUE asignado a WoW y no inspecciona la especialización de cada miembro del grupo en segundo plano."
L["No live "] = "sin vivir"
L["No live member"] = "Ningún miembro vivo"
L["No matching aura active"] = "No hay aura activa activa"
L["No. Automatic selection currently uses only WoW's assigned TANK role. Healers, DPS, classes, specializations, and support targets must be pinned manually with the hover hotkey. This avoids background inspection or polling and keeps the selection deterministic."] = "No. La selección automática actualmente utiliza solo el rol TANQUE asignado a WoW. Los sanadores, DPS, clases, especializaciones y objetivos de apoyo deben fijarse manualmente con la tecla de acceso rápido. Esto evita la inspección de antecedentes o el sondeo y mantiene la selección determinista."
L["Open Group Frames > Priority > Placement. Attach the strip to the right, left, top, or bottom of the active Party/Raid container, or choose Free position and use the dedicated Priority Frames mover in Edit Mode. The same page controls growth, spacing, attachment gap, and alignment offset."] = "Abra Marcos de grupo > Prioridad > Ubicación. Coloque la tira a la derecha, izquierda, arriba o abajo del contenedor Party/Raid activo, o elija la posición Libre y use el motor de Marcos de prioridad dedicado en el modo de edición. La misma página controla el crecimiento, el espaciado, el espacio de unión y el desplazamiento de alineación."
L["Override active: this scope keeps its own aura style. Shared style changes will not replace it until the override is reset."] = "Anulación activa: este visor mantiene su propio estilo de aura. Los cambios de estilo compartido no lo reemplazarán hasta que se restablezca la anulación."
L["Priority Frames does not automatically detect other players' specializations. Automatic selection currently supports WoW-assigned tanks only. Pin an Augmentation Evoker manually with the hover hotkey; Priority Frames does not choose ideal Prescience or Ebon Might targets."] = "Priority Frames no detecta automáticamente las especializaciones de otros jugadores. Actualmente, la selección automática solo admite tanques asignados a WoW. Fije un Evocador de aumento manualmente con la tecla de acceso rápido; Priority Frames no elige objetivos ideales de Presciencia o Poder de Ébano."
L["Priority Frames duplicate automatic tanks and manually pinned current group members into a stable extra strip without removing them from the normal Party or Raid frames. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. They work in parties, raids, and Mythic raids, inherit the active group-frame click-cast behavior, and require the matching base group frames to be enabled."] = "Los marcos de prioridad duplican los tanques automáticos y fijan manualmente a los miembros del grupo actual en una franja adicional estable sin eliminarlos de los marcos normales de grupo o incursión. En un grupo heredan Party Frames; en una incursión heredan los marcos de Incursión activa o Incursión Mítica. Funcionan en grupos, incursiones e incursiones míticas, heredan el comportamiento de transmisión de clic del marco de grupo activo y requieren que se habiliten los marcos de grupo base coincidentes."
L["Shared aura style is the baseline for unit-frame aura text, swipe, border, and timer settings. Party and Raid are group-frame style scopes with their own settings."] = "El estilo de aura compartido es la base para el texto del aura de marco unitario, el deslizamiento, el borde y la configuración del temporizador. Party y Raid son ámbitos de estilo de marco de grupo con sus propias configuraciones."
L["Textures are shared except Party/Raid group-frame overrides. Gradients can be customized per unit or group scope."] = "Las texturas se comparten excepto las anulaciones de marcos de grupo de Grupo/Incursión. Los gradientes se pueden personalizar por unidad o alcance de grupo."
L["This group scope can use custom textures and gradients. Raid also applies to Mythic Raid."] = "Este ámbito de grupo puede utilizar texturas y degradados personalizados. Raid también se aplica a Mythic Raid."
L["This scope can use custom gradients and bar settings. Textures still follow Shared."] = "Este alcance puede usar gradientes personalizados y configuraciones de barra. Las texturas siguen siendo compartidas."
L["This scope follows Shared bar settings. Turn on custom settings here when this scope needs different gradients or bar settings."] = "Este alcance sigue la configuración de la barra compartida. Active la configuración personalizada aquí cuando este alcance necesite diferentes gradientes o configuraciones de barra."
L["Updates after combat"] = "Actualizaciones después del combate."
L["Where can I request a Priority Frames feature?"] = "¿Dónde puedo solicitar una función de Marcos prioritarios?"
L["While grouped, set the hover hotkey on Group Frames > Priority. Hover an MSUF Party, Raid, or Priority frame and press the Priority Frames hotkey to pin or unpin that player. Players cannot be added by typing a name or while outside the current group; a saved absent pin waits and reappears when that player rejoins."] = "Mientras está agrupado, configure la tecla de acceso rápido en Marcos de grupo > Prioridad. Coloca el cursor sobre un marco de grupo, incursión o prioridad de MSUF y presiona la tecla de acceso rápido Marcos de prioridad para fijar o desanclar a ese jugador. No se pueden agregar jugadores escribiendo un nombre o mientras están fuera del grupo actual; un pin ausente guardado espera y reaparece cuando ese jugador se reincorpora."
L["Why are my Priority Frames empty or missing?"] = "¿Por qué faltan o están vacíos mis marcos de prioridad?"
L["Yes. Include tanks automatically selects current group members whose WoW-assigned role is TANK, normally including both you and your co-tank. To show only your co-tank, disable automatic tanks and manually pin the other tank. If WoW has not assigned that player the TANK role, manual pinning is the fallback."] = "Sí. Incluir tanques selecciona automáticamente a los miembros del grupo actual cuyo rol asignado por WoW es TANQUE, normalmente incluyéndote a ti y a tu compañero tanque. Para mostrar solo su co-tanque, desactive los tanques automáticos y fije manualmente el otro tanque. Si WoW no le ha asignado a ese jugador el rol de TANQUE, la opción alternativa es fijarlo manualmente."
L["Yes. Priority Frames inherit the active Party, Raid, or Mythic Raid frame appearance, including configured bars, text, auras, status indicators, and spell indicators. They use the same MSUF click-casting registration and unit behavior, so existing click-cast bindings also work on the duplicated frames."] = "Sí. Los marcos prioritarios heredan la apariencia del marco activo de Grupo, Incursión o Incursión mítica, incluidas barras, texto, auras, indicadores de estado e indicadores de hechizos configurados. Utilizan el mismo registro de transmisión por clic y comportamiento de unidad de MSUF, por lo que los enlaces de transmisión por clic existentes también funcionan en los marcos duplicados."
L["Yes. Priority Frames work in parties, raids, and Mythic raids. In a party or dungeon they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid setup. They do not create a solo strip, and the matching base Party or Raid frames must be enabled."] = "Sí. Los marcos de prioridad funcionan en grupos, incursiones y incursiones míticas. En un grupo o mazmorra heredan Party Frames; en una incursión heredan la configuración de Incursión activa o Incursión Mítica. No crean una franja en solitario y los marcos de grupo o incursión base correspondientes deben estar habilitados."
