L["Applies to the entire castbar: bar, icon, all text, effects, and border. The castbar shares its Unit Frame strata; this value directly sets its frame level, so higher values draw above lower values."] = "Se aplica a toda la barra de lanzamiento: barra, icono, todos los textos, efectos y borde. La barra comparte el estrato de su marco de unidad; este valor define directamente su nivel de marco, por lo que los valores altos se dibujan sobre los bajos."
