L["Each castbar text can override the shared castbar text color. Target text exists on Target and Focus only."] = "Cada texto de la barra de lanzamiento puede anular el color compartido. El texto de objetivo solo existe en Objetivo y Foco."
L["Color for a single text indicator on one frame. Unset indicators follow that frame's font color."] = "Color de un solo indicador de texto en un marco. Sin color propio, el indicador sigue la fuente del marco."
L["Aura Style > Defensive Buffs can follow the frame portrait shape."] = "Estilo de aura > Beneficios defensivos puede seguir la forma del retrato del marco."
L["Cooldown timer urgency plus shared icon border and shadow colors."] = "Urgencia del temporizador de enfriamiento y colores compartidos de borde y sombra del icono."
L["Follow shared settings"] = "Seguir la configuración compartida"
L["Icon Shape"] = "Forma del icono"
L["Keeps Icon Shape synchronized with Aura Style > Shared while the remaining Group Aura settings stay local."] = "Mantiene Forma del icono sincronizada con Estilo de aura > Compartido mientras el resto de ajustes de auras de grupo siguen siendo locales."
L["Shared icon shape"] = "Forma de icono compartida"
L["Visibility modes apply only to unit and group frames. Aura tooltips use their own Show Tooltip switches; even Never does not override them. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "Los modos de visibilidad solo se aplican a los marcos de unidad y de grupo. Las descripciones de auras usan sus propios interruptores Mostrar descripción emergente; ni siquiera la opción nunca los anula. Las auras solo reutilizan el aspecto Blizzard/MSUF seleccionado y la posición del cursor."
L["Applies to the entire castbar: bar, icon, all text, effects, and border. All MSUF elements share this 0-30 order; every part of layer 30 draws above every part of layer 29."] = "Se aplica a toda la barra de lanzamiento: barra, icono, todos los textos, efectos y borde. Todos los elementos de MSUF comparten este orden 0-30; cada parte de la capa 30 se dibuja por encima de cada parte de la capa 29."
L["Display: "] = "Visualización: "
L["Enemy debuffs: hide only exact noisy SpellIDs. Selected Dots on target are handled automatically by that scope's Auto-blacklist toggle."] = "Perjuicios enemigos: oculta solo los SpellID ruidosos exactos. Los DoTs en el objetivo seleccionados se gestionan automáticamente con el interruptor de lista negra automática de ese ámbito."
L["Icon"] = "Icono"
L["Source: this UnitFrame · Ownership: only mine · Harmful DoTs only · "] = "Fuente: este UnitFrame · Propiedad: solo míos · solo DoTs dañinos · "
L["Texture Layer "] = "Capa de textura "
L["Whole Castbar"] = "Toda la barra de lanzamiento"

--- Login welcome message
L["Welcome to Patch %s"] = "Bienvenido al parche %s"
L["Type %s to open the menu."] = "Escribe %s para abrir el menú."

--- Blizzard Raid Manager visibility (Group Frames > Layout > Frame Basics)
L["Always hidden"] = "Siempre oculto"
L["Blizzard Raid Manager"] = "Gestor de bandas de Blizzard"
L["Blizzard's tab at the left screen edge with ready check, raid markers, and role filters. One shared frame, so this setting is the same for Party, Raid, and Mythic Raid."] = "La pestaña de Blizzard en el borde izquierdo de la pantalla con comprobación de estado, marcadores de banda y filtros de rol. Es un único marco compartido, así que este ajuste es el mismo para Grupo, Banda y Banda mítica."
L["Fades the Raid Manager out until the mouse touches it. Ready check, raid markers, and role filters stay reachable, and an expanded panel stays visible until you collapse it again."] = "Atenúa el gestor de bandas hasta que el ratón lo toca. La comprobación de estado, los marcadores de banda y los filtros de rol siguen accesibles, y un panel desplegado permanece visible hasta que vuelvas a plegarlo."
L["Keeps the Raid Manager invisible and click-through at all times. Switch back to reach its buttons again."] = "Mantiene el gestor de bandas invisible y sin capturar clics en todo momento. Vuelve a cambiarlo para acceder a sus botones."
L["Show on mouseover"] = "Mostrar al pasar el ratón"
L["Automatic"] = "Automático"
L["Always visible"] = "Siempre visible"
L["Hides the Raid Manager while MSUF provides the live group frames, and leaves it to WoW otherwise. This is how MSUF has always behaved."] = "Oculta el gestor de bandas mientras MSUF proporciona los marcos de grupo activos, y en caso contrario lo deja en manos de WoW. Así se ha comportado MSUF siempre."
L["Keeps the Raid Manager reachable even with MSUF group frames on. Use this when you still want its ready check, raid markers, and role filters."] = "Mantiene accesible el gestor de bandas incluso con los marcos de grupo de MSUF activos. Úsalo si sigues queriendo su comprobación de estado, marcadores de banda y filtros de rol."
L["Shared by Party, Raid, and Mythic Raid. Automatic keeps the tab hidden while MSUF provides the group frames."] = "Compartido por Grupo, Banda y Banda mítica. Automático mantiene la pestaña oculta mientras MSUF proporciona los marcos de grupo."
L["MSUF detected %s."] = "MSUF detected %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."
L["Second confirmation for %s."] = "Second confirmation for %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Confirm only if you want the whole Unit Frame layout to move with your cooldowns."
L["Confirm anchoring"] = "Confirm anchoring"
L["Continue"] = "Continue"
L["Keep independent"] = "Keep independent"
L["%s detected: Global anchor follows Essential Cooldown Manager. Toggle Cooldown in MSUF Edit Mode to turn it off."] = "%s detectado: el anclaje global sigue al gestor de reutilización esencial. Desactívalo con Cooldown en el modo edición de MSUF."
L["%s detected: Cooldown Manager anchoring is off. Toggle Cooldown in MSUF Edit Mode to turn it on."] = "%s detectado: el anclaje al gestor de reutilización está desactivado. Actívalo con Cooldown en el modo edición de MSUF."
L["Cooldown Manager anchoring (%s)"] = "Anclaje al gestor de reutilización (%s)"
L["Global anchor (%s Anchor)"] = "Anclaje global (anclaje de %s)"
L["Fades all four outer edges; 0% keeps the original texture."] = "Suaviza los cuatro bordes exteriores; 0% conserva la textura original."

-- Menu localization pass 2026-08-06: previously untranslated menu strings.
L["1:1 shows the configured aura pixel size."] = "1:1 muestra el tamaño de aura en píxeles configurado."
L["Aura Options"] = "Opciones de aura"
L["Aura Options and Aura Style belong to this UnitFrame. Global icon appearance: Appearance > Aura Style."] = "Las Opciones de aura y el Estilo de aura pertenecen a este UnitFrame. Apariencia global de iconos: Apariencia > Estilo de aura."
L["Below this value, remaining whole seconds may show one decimal place. Set 0 for whole seconds only."] = "Por debajo de este valor, el tiempo restante puede mostrar un decimal. Usa 0 para mostrar solo segundos enteros."
L["Buff Appearance"] = "Apariencia de mejoras"
L["Debuff Appearance"] = "Apariencia de perjuicios"
L["Global Aura Appearance: Buffs"] = "Apariencia global de auras: Mejoras"
L["Global Aura Appearance: Debuffs"] = "Apariencia global de auras: Perjuicios"
L["Timer colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "Los colores del temporizador se comparten entre auras en vivo de unidad/grupo y todas las vistas previas. Los colores del borde y la sombra de los iconos están en Apariencia > Auras y se configuran por tipo de aura."
L["Click to open the setting that enables this layer."] = "Haz clic para abrir el ajuste que activa esta capa."
L["Controls native Aura tooltips for Spell Icons only."] = "Controla las descripciones emergentes nativas de auras solo para los Iconos de hechizos."
L["Cooldown text format"] = "Formato del texto de reutilización"
L["Copies Buff, Debuff, External Defensive and Spell Icon presentation, including icon zoom, text, swipe, duration bars and ordering. Aura Options, tracked Spell Icons and the global Appearance theme remain unchanged."] = "Copia la presentación de mejoras, desventajas, defensivos externos e Iconos de hechizos, incluidos el zoom del icono, el texto, el barrido, las barras de duración y el orden. Las Opciones de aura, los Iconos de hechizos rastreados y el tema global de Apariencia no cambian."
L["Copies Group Aura visibility, layout, filters, exact/category blacklists, Strata and dispel options. Aura Style and the global Appearance theme remain unchanged."] = "Copia la visibilidad, el diseño, los filtros, las listas negras exactas y por categoría, el nivel de capa y las opciones de disipación de las auras de grupo. El Estilo de aura y el tema global de Apariencia no cambian."
L["Copies this UnitFrame's Aura visibility, layout, filters, blacklists, Custom Aura setup and tracked spells. Aura Style and the global Appearance theme remain unchanged."] = "Copia la visibilidad de auras, el diseño, los filtros, las listas negras, la configuración de auras personalizadas y los hechizos rastreados de este UnitFrame. El Estilo de aura y el tema global de Apariencia no cambian."
L["Copies this UnitFrame's Buff, Debuff, Custom Aura, Player Defensive and Dots on Target presentation, including text, swipe, icon zoom, duration bars, Pandemic and Full-Frame effects. Aura Options and the global Appearance theme remain unchanged."] = "Copia la presentación de mejoras, desventajas, auras personalizadas, defensivos del jugador y DoTs en el objetivo de este UnitFrame, incluidos el texto, el barrido, el zoom del icono, las barras de duración, la pandemia y los efectos a marco completo. Las Opciones de aura y el tema global de Apariencia no cambian."
L["Drag background (%dx)"] = "Arrastrar el fondo (%dx)"
L["Drag to move. Arrow keys nudge."] = "Arrastra para mover. Las teclas de flecha ajustan con precisión."
L["EllesmereUI"] = "EllesmereUI"
L["EllesmereUI Unlock Mode"] = "Modo de desbloqueo de EllesmereUI"
L["Exact X coordinate"] = "Coordenada X exacta"
L["Exact Y coordinate"] = "Coordenada Y exacta"
L["Fit shows the complete aura layout."] = "Ajustar muestra el diseño de auras completo."
L["Global Appearance theme selected only by Aura type. All layout, filters, timers, text and effects stay scope-aware in the corresponding UnitFrame or GroupFrame."] = "Tema global de Apariencia seleccionado únicamente por tipo de aura. Todo el diseño, los filtros, los temporizadores, el texto y los efectos siguen dependiendo del ámbito en el UnitFrame o GroupFrame correspondiente."
L["Individual Style is edited here. Shared icon theme: Appearance > Aura Style."] = "El Estilo individual se edita aquí. Tema de iconos compartido: Apariencia > Estilo de aura."
L["Layout, filters, lists and every container-specific Style live in each frame. Appearance > Aura Style owns only the global icon theme."] = "El diseño, los filtros, las listas y cada Estilo específico de contenedor residen en cada marco. Apariencia > Estilo de aura solo controla el tema global de iconos."
L["Measured from the center of the previewed frame. Positive values move right. Arrow keys and dragging update the same position."] = "Se mide desde el centro del marco en vista previa. Los valores positivos desplazan a la derecha. Las teclas de flecha y el arrastre actualizan la misma posición."
L["Measured from the center of the previewed frame. Positive values move up. Arrow keys and dragging update the same position."] = "Se mide desde el centro del marco en vista previa. Los valores positivos desplazan hacia arriba. Las teclas de flecha y el arrastre actualizan la misma posición."
L["On (default): MSUF frames appear in EllesmereUI Unlock Mode. Turn this off to keep using the native MSUF Edit Mode. MSUF profile positions remain the source of truth."] = "Activado (predeterminado): los marcos de MSUF aparecen en el Modo de desbloqueo de EllesmereUI. Desactívalo para seguir usando el Modo de edición nativo de MSUF. Las posiciones del perfil de MSUF siguen siendo la referencia."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own layout, filters, blacklists and Style; Custom 1-3, Defensive Buffs and Dots on target expose controls appropriate to their content."] = "Abre el marco y despliega Auras. Las mejoras y las desventajas tienen su propio diseño, filtros, listas negras y Estilo; Personalizada 1-3, Beneficios defensivos y DoTs en el objetivo muestran los controles adecuados a su contenido."
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This GroupFrame's individual Style stays here."] = "Abre el tema global de iconos de aura: borde, sombra, colores, margen de carril y encantamientos de arma nativos del jugador. El Estilo individual de este GroupFrame permanece aquí."
L["PERFORMANCE WARNING (12.1): Blizzard can run an OnUpdate every frame on each visible aura button for the full aura while it has a calculated pandemic window, not only while the warning is shown. Enable only if you accept this potentially high combat cost."] = "ADVERTENCIA DE RENDIMIENTO (12.1): Blizzard puede ejecutar un OnUpdate en cada marco para cada botón de aura visible mientras el aura tenga una ventana de pandemia calculada, y no solo mientras se muestra el aviso. Actívalo solo si aceptas este coste potencialmente alto en combate."
L["Paints a stand-in tint on the live GroupFrames so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Aplica un tinte de muestra a los GroupFrames activos para poder valorar la superposición sin una desventaja disipable real. Se desactiva solo al cerrar esta página."
L["Paints a stand-in tint on the live UnitFrame so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Aplica un tinte de muestra al UnitFrame activo para poder valorar la superposición sin una desventaja disipable real. Se desactiva solo al cerrar esta página."
L["Position is controlled by the colored aura handle in Preview."] = "La posición se controla con el tirador de aura de color en la Vista previa."
L["Preview position"] = "Posición de vista previa"
L["Runtime Preview"] = "Vista previa en tiempo real"
L["Runtime Preview: live GroupFrames"] = "Vista previa en tiempo real: GroupFrames activos"
L["Runtime Preview: live UnitFrame"] = "Vista previa en tiempo real: UnitFrame activo"
L["Runtime Preview: live UnitFrame (drag)"] = "Vista previa en tiempo real: UnitFrame activo (arrastrar)"
L["Shape, border and shadow: Appearance > Aura Style > Buffs. All controls here remain Group-scope aware."] = "Forma, borde y sombra: Apariencia > Estilo de aura > Mejoras. Todos los controles de aquí siguen dependiendo del ámbito de grupo."
L["Shared Aura Style"] = "Estilo de aura compartido"
L["Shared Aura Style: Buffs"] = "Estilo de aura compartido: mejoras"
L["Shared Aura Style: Debuffs"] = "Estilo de aura compartido: desventajas"
L["Shared Preview - "] = "Vista previa compartida - "
L["Shows stand-in symbols on the live UnitFrame and lets you drag them into position without a real debuff. Turns itself off when this page closes."] = "Muestra símbolos de muestra en el UnitFrame activo y te permite arrastrarlos a su posición sin una desventaja real. Se desactiva solo al cerrar esta página."
L["Spell Icon Style"] = "Estilo de los Iconos de hechizos"
L["Spell Icon tooltip"] = "Descripción emergente de los Iconos de hechizos"
L["Swipe Direction"] = "Dirección del barrido"
L["This switch is shown only while EllesmereUI is loaded. Disabling it immediately returns MSUF to its own Edit Mode."] = "Este interruptor solo aparece mientras EllesmereUI está cargado. Al desactivarlo, MSUF vuelve de inmediato a su propio Modo de edición."
L["Use - / + or Ctrl + mouse wheel to zoom."] = "Usa - / + o Ctrl + rueda del ratón para hacer zoom."
L["Use EllesmereUI Unlock Mode for MSUF"] = "Usar el Modo de desbloqueo de EllesmereUI para MSUF"
L["Use the colored Texture handle in Preview for exact placement."] = "Usa el tirador de textura de color en la Vista previa para colocarlo con precisión."
L["Zoom changes only this preview, not your Aura settings."] = "El zoom solo cambia esta vista previa, no tus ajustes de aura."

