L["Adds Blizzard's temporary weapon-enchantment buttons to the Player Buff container. This is one shared setting and uses the native aura flow without an MSUF ticker or OnUpdate."] = "Añade los botones de encantamiento de arma temporal de Blizzard al contenedor de mejoras del jugador. Es un único ajuste compartido y usa el flujo de auras nativo, sin temporizador ni OnUpdate de MSUF."
L["Adds an exact harmful aura ID that is missing from the curated list. The aura is still restricted to your current target and your own aura source."] = "Añade un ID exacto de aura dañina que falta en la lista curada. El aura sigue limitada a tu objetivo actual y a tus propias auras."
L["Adds one exact buff to this frame's blacklist."] = "Añade una mejora exacta a la lista negra de este marco."
