L["Adds one exact harmful aura to this Target, Focus, or Boss blacklist. Blizzard applies arbitrary SpellID filters only while the unit is not assistable."] = "Añade un aura dañina exacta a la lista negra de Objetivo, Foco o Jefe. Blizzard aplica filtros arbitrarios de SpellID solo mientras no puedas asistir a la unidad."
