L["Bar Only hides the aura icon. Icon + Bar keeps the icon and draws the duration bar on it."] = "Solo barra oculta el icono del aura. Icono + barra conserva el icono y dibuja la barra de duración sobre él."
L["Bar keeps the normal statusbar. Follow Player Power mirrors the independent detached Player power shape. Orb uses a single vertical fill."] = "Barra mantiene la barra de estado normal. Seguir recurso del jugador refleja la forma del recurso del jugador desacoplado. Orbe usa un único relleno vertical."
L["Big Defensive"] = "Gran defensivo"
