L["Changes only the detached Player Powerbar. Class Resource shape on the left changes only Class Resources."] = "Cambia solo la barra de recurso del jugador desacoplada. La forma del recurso de clase a la izquierda cambia solo los recursos de clase."
L["Class Resource Preview"] = "Vista previa del recurso de clase"
L["Class Resource and Player Power follow existing frames. Custom uses the slider below. Width is resolved only during layout refresh."] = "El recurso de clase y el recurso del jugador siguen a los marcos existentes. Personalizado usa el deslizador de abajo. El ancho solo se resuelve al actualizar el diseño."
L["Controls only the second HP bar outline. Bar uses four outside border edges; shapes use their fixed edge texture. 0 disables only the outline."] = "Controla solo el contorno de la segunda barra de vida. Barra usa los cuatro bordes exteriores; las formas usan su textura de borde fija. 0 desactiva únicamente el contorno."
L["Controls only this second HP bar. The normal Player unitframe HP text remains separate."] = "Controla solo esta segunda barra de vida. El texto de vida normal del marco del jugador sigue siendo independiente."
L["Controls this aura lane independently. Always / Out of Combat / Modifier / Never under Global Style > Miscellaneous affect only unit and group frames. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "Controla este carril de auras de forma independiente. Siempre / Fuera de combate / Modificador / Nunca, en Estilo global > Misceláneo, solo afectan a los marcos de unidad y de grupo. Las auras solo reutilizan el aspecto Blizzard/MSUF elegido y la posición del cursor."
L["Cooldown swipe direction"] = "Dirección del barrido de reutilización"
L["Core feature enabled by default for new profiles and once for existing profiles. It works as a normal defensive buff bar without an enabled portrait. Turn this off to disable both bar and portrait-position display."] = "Función principal activada de forma predeterminada en los perfiles nuevos y una sola vez en los existentes. Funciona como una barra de mejoras defensivas normal aunque no haya retrato activo. Desactívala para quitar tanto la barra como la presentación en la posición del retrato."
L["Crowd Control"] = "Control de masas"
L["Curated Retail 12.0+ and 12.1 DoT auras. Tracking is restricted to this UnitFrame's unit and your own aura source; Boss settings bind separately to boss1 through boss5."] = "Auras de DoT curadas para Retail 12.0+ y 12.1. El seguimiento se limita a la unidad de este UnitFrame y a tus propias auras; los ajustes de jefe se vinculan por separado de boss1 a boss5."
L["Custom Spell ID"] = "ID de hechizo personalizado"
L["Dark Border"] = "Borde oscuro"
L["Disabled by default. Blizzard's native implementation enables a per-frame OnUpdate for each visible aura button as soon as that aura has a calculated pandemic window; this can begin before the warning becomes visible."] = "Desactivado de forma predeterminada. La implementación nativa de Blizzard activa un OnUpdate por marco en cada botón de aura visible en cuanto esa aura tiene una ventana de pandemia calculada; esto puede empezar antes de que el aviso sea visible."
L["Dispellable by Group"] = "Disipable por el grupo"
L["Dispellable by Me (Raid)"] = "Disipable por mí (banda)"
L["Dispellable by group"] = "Disipable por el grupo"
