L["Duration bar display"] = "Presentación de la barra de duración"
L["Duration bar fill mode"] = "Modo de relleno de la barra de duración"
L["Duration bar position"] = "Posición de la barra de duración"
L["Edge strength of every detached Player power shape, including Bar, Round, Crystal and Orb. 0 disables only that edge."] = "Intensidad del borde de cada forma del recurso del jugador desacoplado, incluidos Barra, Redondo, Cristal y Orbe. 0 desactiva únicamente ese borde."
L["Elapsed / Total"] = "Transcurrido / total"
L["Enable defensive buffs"] = "Activar mejoras defensivas"
L["Enable tracked DoTs"] = "Activar DoTs monitorizados"
L["Enter a Spell ID, paste a spell link, or type a spell name. The visible helpful aura is matched even when its buff ID differs from the cast Spell ID."] = "Introduce un ID de hechizo, pega un enlace de hechizo o escribe un nombre de hechizo. El aura beneficiosa visible se reconoce aunque su ID de mejora difiera del ID del hechizo lanzado."
L["Enter a Spell ID, paste a spell link, or type a spell name. This whitelist tracks exact Spell IDs."] = "Introduce un ID de hechizo, pega un enlace de hechizo o escribe un nombre de hechizo. Esta lista blanca monitoriza IDs de hechizo exactos."
L["Essential cooldown viewer"] = "Visor de reutilizaciones esenciales"
L["Exact aura tracking"] = "Seguimiento exacto de auras"
L["External Defensive"] = "Defensivo externo"
L["External Defensive Player"] = "Defensivo externo (jugador)"
L["Fill Mode"] = "Modo de relleno"
L["Focus off"] = "Foco desactivado"
L["Focus on"] = "Foco activado"
L["Global follows the normal MSUF health color mode. Class Color forces your class color. Dark Mode forces the configured dark bar color. HP Gradient colors only this second HP bar by current health."] = "Global sigue el modo de color de vida normal de MSUF. Class Color impone el color de tu clase. Dark Mode impone el color de barra oscuro configurado. HP Gradient colorea solo esta segunda barra de vida según la vida actual."
L["Global icon shape"] = "Forma global del icono"
L["HP Color"] = "Color de vida"
L["HP Outline"] = "Contorno de vida"
L["HP Shape"] = "Forma de la barra de vida"
L["HP only"] = "Solo vida"
L["Healers only"] = "Solo sanadores"
L["Hide permanent auras"] = "Ocultar auras permanentes"
L["Hides this scope's selected DoT Spell IDs from the same UnitFrame's normal Debuff container while Dots on target is enabled. Blizzard's blacklist is SpellID-based, so the same spell cast by another player is hidden there too."] = "Oculta los IDs de hechizo de DoT seleccionados en este ámbito del contenedor de desventajas normal del mismo UnitFrame mientras DoTs en el objetivo esté activo. La lista negra de Blizzard funciona por SpellID, así que el mismo hechizo lanzado por otro jugador también se oculta allí."
L["Highest priority only"] = "Solo la de mayor prioridad"
L["Icon Border & Shadow"] = "Borde y sombra del icono"
L["Include Nameplate-only"] = "Incluir solo de placa de nombre"
L["Inside Left"] = "Interior izquierda"
L["Inside Right"] = "Interior derecha"
L["Keeps detached Player power attached to the Class Resource bar. Player power controls are disabled while this connection is active."] = "Mantiene el recurso del jugador desacoplado unido a la barra de recurso de clase. Los controles del recurso del jugador se desactivan mientras esta conexión está activa."
L["Keeps the configured portrait size and position as an invisible anchor so the defensive icon can remain there while the portrait itself is disabled."] = "Conserva el tamaño y la posición configurados del retrato como ancla invisible para que el icono defensivo pueda permanecer ahí mientras el retrato está desactivado."
L["Keeps the configured portrait size, position, and shape as an invisible anchor for tracked DoTs while the portrait itself is disabled."] = "Conserva el tamaño, la posición y la forma configurados del retrato como ancla invisible para los DoTs monitorizados mientras el retrato está desactivado."
L["Limits simultaneous DoT icons at the portrait from 1 to 8. Additional icons grow outward using this DoT lane's configured Growth direction."] = "Limita los iconos de DoT simultáneos en el retrato de 1 a 8. Los iconos adicionales crecen hacia fuera según la dirección de crecimiento configurada para este carril de DoT."
L["Limits the number of simultaneous defensive icons at the portrait from 1 to 8. Existing profiles remain at 1 until this value is changed."] = "Limita el número de iconos defensivos simultáneos en el retrato de 1 a 8. Los perfiles existentes se mantienen en 1 hasta que cambies este valor."
L["Lists every MSUF slash command in chat, diagnostics included."] = "Lista en el chat todos los comandos de barra de MSUF, diagnósticos incluidos."
L["Max portrait icons"] = "Máx. de iconos en el retrato"
L["Maximum debuff duration"] = "Duración máxima de la desventaja"
L["Moves all detached Player power text slots together. Slot X/Y controls below add per-slot offsets."] = "Mueve a la vez todas las ranuras de texto del recurso del jugador desacoplado. Los controles X/Y de ranura de abajo añaden desplazamientos individuales."
L["Moves the Player power bar out of the unit frame. Anchor connects it to the Class Resources stack; Sync only follows the stack width."] = "Saca la barra de recurso del jugador del marco de unidad. Anclar la conecta a la pila de recursos de clase; Sincronizar solo adopta el ancho de la pila."
L["Native Aura Flow"] = "Flujo de auras nativo"
L["Blizzard Buff & Debuff Frames"] = "Marcos de beneficios y perjuicios de Blizzard"
L["Hide Blizzard Buff and Debuff Frames"] = "Ocultar los marcos de beneficios y perjuicios de Blizzard"
L["Hides only Blizzard's player Buff Frame and normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "Oculta solo el marco de beneficios del jugador de Blizzard y los iconos de perjuicios normales cerca del minimapa. Las auras privadas y los avisos de perjuicios letales permanecen visibles."
L["Buffs hidden"] = "Beneficios ocultos"
L["Buffs visible"] = "Beneficios visibles"
L["Debuffs hidden"] = "Perjuicios ocultos"
L["Debuffs visible"] = "Perjuicios visibles"
L["Hide Blizzard Buff Frame"] = "Ocultar el marco de beneficios de Blizzard"
L["Hide Blizzard Debuff Frame"] = "Ocultar el marco de perjuicios de Blizzard"
L["Hides Blizzard's player Buff Frame near the minimap."] = "Oculta el marco de beneficios del jugador de Blizzard cerca del minimapa."
L["Hides only Blizzard's normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "Oculta solo los iconos de perjuicios normales de Blizzard cerca del minimapa. Las auras privadas y los avisos de perjuicios letales permanecen visibles."
L["Native size"] = "Tamaño nativo"
L["Native stealable marker"] = "Marcador nativo de robable"
L["Native weapon enchant auras"] = "Auras nativas de encantamiento de arma"
L["No roles"] = "Ningún rol"
L["No width limit"] = "Sin límite de ancho"
L["Not Cancelable"] = "No cancelable"
L["Not Cancelable Player"] = "No cancelable (jugador)"
L["Off shows debuffs of any duration. Otherwise, debuffs whose total duration exceeds this number of seconds are hidden."] = "Desactivado muestra desventajas de cualquier duración. En caso contrario, se ocultan las desventajas cuya duración total supere este número de segundos."
L["One per dispel type"] = "Uno por tipo de disipación"
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This frame's container Style stays here."] = "Abre el tema global de iconos de aura: borde, sombra, colores, margen de carril y encantamientos de arma nativos del jugador. El Estilo del contenedor de este marco permanece aquí."
L["Optional interpolation for this second HP bar. Off keeps direct native SetValue updates."] = "Interpolación opcional para esta segunda barra de vida. Desactivada mantiene las actualizaciones nativas directas de SetValue."
L["Optional presentation mode; the Defensive Buffs feature itself does not require a portrait. With an enabled portrait, the first icon occupies it. When the portrait is off, enable the position option below to keep the icons there; otherwise MSUF safely falls back to the normal defensive bar."] = "Modo de presentación opcional; la función Beneficios defensivos no requiere retrato. Con el retrato activado, el primer icono lo ocupa. Con el retrato desactivado, activa la opción de posición de abajo para mantener ahí los iconos; de lo contrario, MSUF vuelve de forma segura a la barra defensiva normal."
L["Orb Size"] = "Tamaño del orbe"
L["Pandemic Warning & Style"] = "Aviso de pandemia y estilo"
L["Pandemic color"] = "Color de pandemia"
L["Places Player power text on the detached power bar. When off, the same Player power text remains positioned by the normal text layout."] = "Coloca el texto del recurso del jugador sobre la barra de recurso desacoplada. Si está desactivado, ese mismo texto se sigue colocando según el diseño de texto normal."
L["Places the duration bar at the top or bottom edge of the aura slot."] = "Coloca la barra de duración en el borde superior o inferior de la ranura del aura."
L["Player Text Outline"] = "Contorno del texto del jugador"
L["Power Bar Outline"] = "Contorno de la barra de recurso"
L["Power Text On Bar"] = "Texto de recurso sobre la barra"
L["Power anchors use the Player power bar when it is visible; otherwise the HP bar falls back to the Class Resource anchor."] = "Los anclajes de recurso usan la barra de recurso del jugador cuando está visible; en caso contrario, la barra de vida recurre al anclaje del recurso de clase."
L["Raid In Combat"] = "Banda en combate"
L["Raid In Combat Player"] = "Banda en combate (jugador)"
L["Raid Player"] = "Banda (jugador)"
L["Remaining / Total"] = "Restante / total"
L["Remaining shrinks as the aura expires. Elapsed grows until the aura expires."] = "Restante se reduce a medida que el aura expira. Transcurrido crece hasta que el aura expira."
L["Remaining time below this value uses one decimal place. Timers show unitless seconds below 1 minute and localized minutes above it. Set 0 for whole seconds only."] = "Por debajo de este valor, el tiempo restante usa un decimal. Los temporizadores muestran segundos sin unidad por debajo de 1 minuto y minutos localizados por encima. Usa 0 para mostrar solo segundos enteros."
L["Remove from blacklist"] = "Quitar de la lista negra"
L["Remove from whitelist"] = "Quitar de la lista blanca"
L["Renders a second native Player health bar. The normal Player unitframe HP bar is untouched, so you can show HP twice."] = "Dibuja una segunda barra de vida nativa del jugador. La barra de vida normal del marco del jugador no se toca, así que puedes mostrar la vida dos veces."
L["Replaces the normal DoT lane with portrait-sized icons. The first icon exactly follows this frame's portrait width, height, and shape."] = "Sustituye el carril de DoT normal por iconos del tamaño del retrato. El primer icono sigue exactamente el ancho, el alto y la forma del retrato de este marco."
L["Runs /msuf reset for frame positions and visibility."] = "Ejecuta /msuf reset para las posiciones y la visibilidad de los marcos."
L["Second Player HP Bar"] = "Segunda barra de vida del jugador"
L["Sets the Player font scope used by detached Power text. Player Name and HP text share this outline setting."] = "Define el ámbito de fuente del jugador que usa el texto de recurso desacoplado. El nombre del jugador y el texto de vida comparten este ajuste de contorno."
L["Show DoTs at portrait position"] = "Mostrar DoTs en la posición del retrato"
L["Show buffs at portrait position"] = "Mostrar mejoras en la posición del retrato"
L["Show cooldown text on portrait"] = "Mostrar texto de reutilización en el retrato"
L["Shows the active defensive buff's remaining duration over its portrait icon. Blizzard updates the text natively."] = "Muestra la duración restante de la mejora defensiva activa sobre su icono de retrato. Blizzard actualiza el texto de forma nativa."
L["Shows the selected class/spec resource below without changing your character, spec or saved settings."] = "Muestra abajo el recurso de la clase o especialización seleccionada sin cambiar tu personaje, tu especialización ni tus ajustes guardados."
L["Shows the tracked DoT's remaining duration over its portrait icon. Blizzard updates the duration natively."] = "Muestra la duración restante del DoT monitorizado sobre su icono de retrato. Blizzard actualiza la duración de forma nativa."
L["Simple presets for Player power text while detached power is managed by Class Resources. Custom Slots means the existing slot layout is kept until you choose a preset."] = "Ajustes preestablecidos sencillos para el texto del recurso del jugador mientras los recursos de clase gestionan el recurso desacoplado. Ranuras personalizadas significa que se conserva el diseño de ranuras actual hasta que elijas un ajuste preestablecido."
L["Smooth Fill"] = "Relleno suave"
L["Spell Text"] = "Texto del hechizo"
L["Stops blocking this aura."] = "Deja de bloquear esta aura."
L["Sync Width"] = "Sincronizar ancho"
L["Tanks only"] = "Solo tanques"
L["Target DoT"] = "DoT en el objetivo"
L["Target off"] = "Objetivo desactivado"
L["Target on"] = "Objetivo activado"
L["Time Text"] = "Texto de tiempo"
L["Track this predefined defensive buff. The setting applies to both the defensive bar and the optional portrait icon."] = "Monitorizar esta mejora defensiva predefinida. El ajuste se aplica tanto a la barra defensiva como al icono opcional del retrato."
L["Tracked buffs viewer"] = "Visor de mejoras monitorizadas"
L["Tracks your selected harmful auras on this UnitFrame's unit. Boss frames use their own boss1 through boss5 unit token."] = "Monitoriza las auras dañinas que selecciones en la unidad de este UnitFrame. Los marcos de jefe usan sus propios identificadores de unidad, de boss1 a boss5."
L["Turns Blizzard token filters on or off for this frame. The first change automatically creates frame-specific rules; migrated Shared rules remain Shared until edited."] = "Activa o desactiva los filtros de identificador de Blizzard para este marco. El primer cambio crea automáticamente reglas propias del marco; las reglas compartidas migradas siguen siendo compartidas hasta que las edites."
L["Unavailable cast fill"] = "Relleno de lanzamiento no disponible"
L["Up (Single Column)"] = "Hacia arriba (una columna)"
L["Use Player HP Text"] = "Usar el texto de vida del jugador"
L["Use portrait position while portrait is off"] = "Usar la posición del retrato con el retrato desactivado"
L["Used only when this HP bar is explicitly set to Orb. Follow Player Power inherits the Player power orb size instead."] = "Solo se usa cuando esta barra de vida está explícitamente en Orbe. Seguir recurso del jugador hereda en su lugar el tamaño del orbe del recurso del jugador."
L["Uses Blizzard's 12.1 AuraButton stealable filter. It adds no MSUF aura scan, ticker, or OnUpdate."] = "Usa el filtro de robables de AuraButton de Blizzard 12.1. No añade ningún escaneo de auras, temporizador ni OnUpdate de MSUF."
L["Uses Player HP text settings and copies already-rendered Player HP text when it is current. Local Text X/Y still belong to this bar."] = "Usa los ajustes del texto de vida del jugador y copia el texto ya dibujado cuando está actualizado. Los valores locales de texto X/Y siguen perteneciendo a esta barra."
L["Uses the Class Resource width for detached Player power without making Class Resources own the Player power controls."] = "Usa el ancho del recurso de clase para el recurso del jugador desacoplado sin que los recursos de clase se apropien de sus controles."
L["Utility cooldown viewer"] = "Visor de reutilizaciones auxiliares"
L["Visible behind the filled HP amount. At 100% HP the fill covers the background; Outline 0 does not disable this texture."] = "Visible detrás de la vida rellenada. Al 100 % de vida el relleno cubre el fondo; un contorno de 0 no desactiva esta textura."
L["Weapon Enchants Off"] = "Encantamientos de arma desactivados"
L["Weapon Enchants On"] = "Encantamientos de arma activados"
L["While the defensive bar or portrait icon is enabled, hides every enabled tracked defensive from the normal player Buffs lane. Disabled defensive entries remain visible there."] = "Mientras la barra defensiva o el icono del retrato estén activos, oculta del carril de mejoras normal del jugador todos los defensivos monitorizados activos. Las entradas defensivas desactivadas siguen visibles ahí."
L["Whole frame"] = "Marco completo"
L["Width Mode"] = "Modo de ancho"

-- Menu localization pass 2026-08-06 (part 3): FAQ answers and search keyword blobs that are concatenated in source.
L["Bar Background Tint Custom color in Dark Mode background backgrond backround bg backdrop opacity alpha"] = "Tinte de fondo de barra Color personalizado en modo oscuro fondo trasfondo bg opacidad alfa background backdrop"
L["Frame Basics Enable Load Conditions Transparency Range Fade player target focus pet gone missing invisible"] = "Básicos del marco Activar Condiciones de carga Opacidad Desvanecimiento por distancia jugador objetivo foco mascota ausente invisible"
L["Frame Basics Smooth fill Power Bar Smooth fill health animation power animation soft fill weiche Fuellung"] = "Básicos del marco Relleno suave Barra de recurso Relleno suave animación de vida animación de recurso smooth fill"
L["General Use MSUF group frames If this switch is off enable disable turn off hide raid party mythic"] = "General Usar marcos de grupo de MSUF Si este interruptor está desactivado activar desactivar ocultar banda grupo mítica"
L["Group Frames Layout Smooth health fill Health Text Power Bar Smooth fill party raid weiche Fuellung"] = "Marcos de grupo/banda Diseño Relleno suave de vida Texto de vida Barra de recurso Relleno suave grupo banda smooth fill"
L["Group Frames Layout Transparency opacity fade target in combat out of combat alpha whole frame bars HP backdrop HP fill HP track preserve HP color"] = "Marcos de grupo/banda Diseño Opacidad transparencia desvanecer objetivo en combate fuera de combate alfa marco completo barras vida fondo relleno de vida pista de vida conservar color de vida"
L["MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from each unit page > Auras or Group Frames > Auras."] = "El Modo de edición de MSUF mueve marcos y barras de lanzamiento compatibles. La colocación de los iconos de aura se controla desde la página de cada unidad > Auras o en Marcos de grupo/banda > Auras."
L["Miscellaneous misc global style language menu behavior startup notices tooltips blizzard frames minimap sounds"] = "Miscelánea varios estilo global idioma comportamiento del menú avisos de inicio descripciones marcos de Blizzard minimapa sonidos"
L["Name Shortening Use custom settings for this scope Overrides Party Raid group frame name truncation font override shared changes"] = "Acortar nombres Usar ajustes personalizados para este ámbito Anula grupo banda acortar nombres en marcos de grupo anulación de fuente cambios compartidos"
L["Open Appearance > Auras for scope-aware cooldown text, stack text, swipe, and duration-bar styling. Timer colors remain under Colors > Auras."] = "Abre Apariencia > Auras para el texto de reutilización, el texto de acumulaciones, el barrido y el estilo de la barra de duración según el ámbito. Los colores del temporizador siguen en Colores > Auras."
L["Open Boss Frames > Auras > Debuffs. SpellID blacklist entries, Blizzard filters, placement, and preview live together there; styling remains under Appearance > Auras."] = "Abre Marcos de jefe > Auras > Desventajas. Las entradas de lista negra por SpellID, los filtros de Blizzard, la colocación y la vista previa están juntos ahí; el estilo sigue en Apariencia > Auras."
L["Open Global Style > Miscellaneous > Unitframe tooltips to control tooltip source, anchor, visibility mode, and modifier key for MSUF unit and group frames."] = "Abre Estilo global > Miscelánea > Descripciones de marcos de unidad para controlar la fuente, el anclaje, el modo de visibilidad y la tecla modificadora de las descripciones en los marcos de unidad y de grupo de MSUF."
L["Open Global Style > Miscellaneous for language, menu behavior, startup notices, tooltips, Blizzard frames, minimap icon, and sounds."] = "Abre Estilo global > Miscelánea para idioma, comportamiento del menú, avisos de inicio, descripciones, marcos de Blizzard, icono del minimapa y sonidos."
L["Open Group Frames > Layout > Range Fade. Affects chooses frame or HP fading, and the alpha sliders control out-of-range and offline opacity."] = "Abre Marcos de grupo/banda > Diseño > Desvanecimiento por distancia. Afecta elige entre desvanecer el marco o la vida, y los deslizadores de alfa controlan la opacidad fuera de rango y sin conexión."
L["Open Group Frames > Layout > Transparency. Opacity controls in-combat and out-of-combat alpha; Fade target chooses whole frame, bars, HP, or backdrop. Backdrop and Health layers set base color, HP fill, and HP track opacity."] = "Abre Marcos de grupo/banda > Diseño > Opacidad. Opacidad controla el alfa en combate y fuera de combate; Objetivo del desvanecimiento elige marco completo, barras, vida o fondo. Las capas Fondo y Vida definen el color base y la opacidad del relleno y de la pista de vida."
L["Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Layout > Resource Bar > Smooth fill."] = "Abre Marcos de grupo/banda > Diseño para Relleno suave de vida. Para las barras de recurso de los marcos de grupo, abre Marcos de grupo/banda > Diseño > Barra de recursos > Relleno suave."
L["Open Group Frames > Layout, choose Party, Raid, or Mythic at the top, then turn off Use MSUF group frames. Use If this switch is off to choose whether Blizzard frames show normally or both frame systems stay hidden."] = "Abre Marcos de grupo/banda > Diseño, elige Grupo, Banda o Mítica arriba y desactiva Usar marcos de grupo de MSUF. Usa Si este interruptor está desactivado para elegir si los marcos de Blizzard se muestran con normalidad o si ambos sistemas de marcos quedan ocultos."
L["Open Group Frames > Layout. Frame Basics and Sorting control player/self visibility and how player units are ordered in group frames."] = "Abre Marcos de grupo/banda > Diseño. Básicos del marco y Ordenar controlan la visibilidad del jugador y de ti mismo, así como el orden de las unidades en los marcos de grupo."
L["Open Group Frames > Layout. Frame Basics/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior."] = "Abre Marcos de grupo/banda > Diseño. Básicos del marco/Diseño controla el ancho, el alto, el espaciado, las columnas y el crecimiento; Escalado del marco controla el comportamiento de escala."
L["Open Group Frames > Status & Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "Abre Marcos de grupo/banda > Estado e indicadores para iconos de estado, rol/líder/asistente, comprobación de preparación, resplandor de foco y otros indicadores de estado de los marcos de grupo."
L["Open Player > Auras, then turn off Buffs for the player frame. Scope-aware text and cooldown styling remains under Appearance > Auras."] = "Abre Jugador > Auras y desactiva Mejoras para el marco del jugador. El estilo de texto y de reutilización según el ámbito sigue en Apariencia > Auras."
L["Open a unit page, then use Range Fade. It is available for Target, Target of Target, Focus, Focus Target, Pet, and Boss."] = "Abre una página de unidad y usa Desvanecimiento por distancia. Está disponible para Objetivo, Objetivo del objetivo, Foco, Objetivo del foco, Mascota y Jefe."
L["Open the affected UnitFrame > Auras for icon size, placement, and filters. Use Appearance > Auras for scope-aware text and cooldown styling."] = "Abre el UnitFrame afectado > Auras para el tamaño del icono, la colocación y los filtros. Usa Apariencia > Auras para el texto y el estilo de reutilización según el ámbito."
L["Open the affected UnitFrame > Auras or Group Frames > Auras and reduce visible counts, timer text, or unnecessary native filter rules."] = "Abre el UnitFrame afectado > Auras o Marcos de grupo/banda > Auras y reduce el número de auras visibles, el texto del temporizador o las reglas de filtro nativas innecesarias."
L["Open the affected UnitFrame > Auras, choose Buffs or Debuffs, then adjust filters, icon size, rows, caps, and spacing. Party/Raid settings are in Group Frames > Auras."] = "Abre el UnitFrame afectado > Auras, elige Mejoras o Desventajas y ajusta filtros, tamaño de icono, filas, límites y espaciado. Los ajustes de grupo y banda están en Marcos de grupo/banda > Auras."
L["Open the unit page > Auras or the aura Position Popup for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode."] = "Abre la página de unidad > Auras o la ventana emergente de posición de auras para colocar las auras del marco de unidad. Los iconos de mejora y desventaja se configuran como diseño de auras, no se mueven con el Modo de edición de MSUF."
L["Range Fade group frame range check raid range check party range check out of range alpha offline opacity affects frame HP"] = "Desvanecimiento por distancia marco de grupo comprobación de rango banda grupo fuera de rango alfa opacidad sin conexión afecta marco vida"
L["Range Fade unit frame range check range checker distance check out of range range alpha distance fade target targettarget focus focustarget pet boss"] = "Desvanecimiento por distancia marco de unidad comprobación de rango comprobación de distancia fuera de rango alfa de rango objetivo objetivo del objetivo foco objetivo del foco mascota jefe"
L["Rounded Texture Rounded frame texture Unit frames Group frames Power bars Mouseover highlights rounded frames round corners"] = "Textura redondeada Textura de marco redondeada Marcos de unidad Marcos de grupo Barras de recurso Resaltados al pasar el ratón marcos redondeados esquinas redondeadas"
L["Status icons Indicator Level Enabled Anchor X Offset Y Offset Size Layer level text level indicator show level player level target level"] = "Iconos de estado Indicador Nivel Activado Punto de anclaje Desplazamiento X Desplazamiento Y Tamaño Capa texto de nivel indicador de nivel nivel del jugador nivel del objetivo"
L["Text anchor offset font size layer spacing split spacing overlaps bars portraits status icons"] = "Texto punto de anclaje desplazamiento tamaño de fuente capa orden de dibujo espaciado espaciado dividido solapamientos barras retratos iconos de estado"
L["Use Group Frames > Layout for frame size and spacing, Auras for Buff/Debuff placement, and Status & Indicators for fixed-position status icons."] = "Usa Marcos de grupo/banda > Diseño para el tamaño y el espaciado de los marcos, Auras para la colocación de mejoras y desventajas, y Estado e indicadores para los iconos de estado de posición fija."
L["Use Group Frames pages: Layout for size, growth, sorting, bars, and text; Auras for Buff/Debuff placement, and Status & Indicators for status icons."] = "Usa las páginas de Marcos de grupo/banda: Diseño para tamaño, crecimiento, orden, barras y texto; Auras para la colocación de mejoras y desventajas, y Estado e indicadores para los iconos de estado."
L["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, text, and interrupt options."] = "Usa la página de unidad para los interruptores de barra de lanzamiento por unidad y Estilo global > Barra de lanzamiento para texturas, dirección, texto y opciones de interrupción compartidas."
L["Welcome to Class Resources!\n\nWould you like to automatically set up a\ndetached Class Bar positioned above your\nEssential Cooldowns?\n\nThis configures class resource visibility,\nanchoring, width matching and detached\nPlayer Power in one click.\n\nYou can always run this later via the\n|cff00ff00Quick Setup: Class Bar|r button below."] = "¡Bienvenido a Recursos de clase!\n\n¿Quieres configurar automáticamente una\nbarra de clase desacoplada situada sobre tus\nreutilizaciones esenciales?\n\nEsto ajusta la visibilidad del recurso de clase,\nel anclaje, la coincidencia de ancho y el recurso\ndel jugador desacoplado en un solo clic.\n\nSiempre puedes hacerlo más tarde con el botón\n|cff00ff00Configuración rápida: barra de clase|r de abajo."
L["External Edit Mode"] = "External Edit Mode"
L["Show Grid2 in MSUF Edit Mode"] = "Show Grid2 in MSUF Edit Mode"
L["Grid2 Edit Mode integration"] = "Grid2 Edit Mode integration"
L["On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."] = "On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."
